export const APP_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>WRL - Tax Invoice</title>\n<style>\n  :root{\n    --purple:#4b2683; --purple-dark:#3a1d68; --orange:#ff5500;\n    --bg:#f4f2f8; --card:#ffffff; --line:#e3def0; --ink:#2b2540; --muted:#7a7394;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  body{font-family:'Segoe UI',Roboto,Arial,sans-serif; background:var(--bg); color:var(--ink); font-size:14px;}\n  .brand-name-purple{color:var(--purple); font-weight:800; letter-spacing:2px;}\n  .brand-name-orange{color:var(--orange); font-weight:800; letter-spacing:3px;}\n\n  /* ---------- TOP BAR ---------- */\n  .topbar{display:flex; align-items:center; gap:14px; flex-wrap:wrap;\n    background:linear-gradient(135deg,var(--purple) 0%,var(--purple-dark) 100%);\n    padding:10px 18px; color:#fff; position:sticky; top:0; z-index:50;\n    box-shadow:0 2px 10px rgba(60,30,110,.35);}\n  .topbar img{height:52px; display:block; border:none; outline:none; box-shadow:none; background:transparent; border-radius:0;}\n  .topbar .tb-title{flex:1; min-width:180px;}\n  .topbar .tb-title h1{font-size:18px; letter-spacing:1px; font-weight:800;}\n  .topbar .tb-title span{font-size:11px; opacity:.85; letter-spacing:1px;}\n  .tb-controls{display:flex; align-items:center; gap:8px; flex-wrap:wrap;}\n  .branch-wrap{display:flex; align-items:center; gap:6px; background:rgba(255,255,255,.14);\n    padding:5px 8px; border-radius:8px; border:1px solid rgba(255,255,255,.25);}\n  .branch-wrap label{font-size:11px; letter-spacing:.5px; opacity:.9;}\n  select,input,textarea{font-family:inherit; font-size:13px; color:var(--ink);}\n  #branchSelect{padding:6px 8px; border-radius:6px; border:1px solid var(--line); min-width:190px; background:#fff;}\n  .btn{border:none; border-radius:8px; padding:9px 14px; font-size:13px; font-weight:700;\n    cursor:pointer; letter-spacing:.3px; transition:.15s; display:inline-flex; align-items:center; gap:6px;}\n  .btn:active{transform:scale(.97);}\n  .btn-orange{background:var(--orange); color:#fff;}\n  .btn-orange:hover{background:#e64d00;}\n  .btn-white{background:#fff; color:var(--purple);}\n  .btn-white:hover{background:#efe9fa;}\n  .btn-ghost{background:rgba(255,255,255,.14); color:#fff; border:1px solid rgba(255,255,255,.35);}\n  .btn-ghost:hover{background:rgba(255,255,255,.25);}\n  .sync-info{font-size:11px; opacity:.9; margin-left:2px;}\n\n  /* ---------- LAYOUT ---------- */\n  .wrap{display:grid; grid-template-columns:1fr 340px; gap:16px; padding:16px; max-width:1400px; margin:0 auto;}\n  @media(max-width:980px){.wrap{grid-template-columns:1fr;}}\n  .card{background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; margin-bottom:16px;\n    box-shadow:0 2px 8px rgba(75,38,131,.06);}\n  .card h3{font-size:13px; text-transform:uppercase; letter-spacing:1px; color:var(--purple);\n    border-bottom:2px solid var(--orange); display:inline-block; padding-bottom:4px; margin-bottom:12px;}\n  .grid2{display:grid; grid-template-columns:1fr 1fr; gap:10px;}\n  .grid3{display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px;}\n  @media(max-width:640px){.grid2,.grid3{grid-template-columns:1fr;}}\n  .fld{display:flex; flex-direction:column; gap:4px;}\n  .fld label{font-size:11px; font-weight:700; color:var(--muted); letter-spacing:.4px; text-transform:uppercase;}\n  .fld input,.fld textarea,.fld select{padding:8px 10px; border:1px solid var(--line); border-radius:7px; background:#fbfaff; width:100%;}\n  .fld input:focus,.fld textarea:focus,.fld select:focus{outline:none; border-color:var(--purple); box-shadow:0 0 0 3px rgba(75,38,131,.12);}\n  .fld textarea{resize:vertical; min-height:58px;}\n  .country-badge{display:inline-block; font-size:11px; font-weight:800; padding:3px 10px; border-radius:20px;\n    background:var(--purple); color:#fff; letter-spacing:1px;}\n  .autosave-note{font-size:11px; color:var(--muted); margin-top:8px;}\n  .autosave-note b{color:var(--orange);}\n\n  /* ---------- ITEMS TABLE ---------- */\n  table.items{width:100%; border-collapse:collapse; margin-top:4px;}\n  table.items th{background:var(--purple); color:#fff; font-size:11px; letter-spacing:.6px; padding:9px 8px; text-align:left;}\n  table.items td{padding:6px 8px; border-bottom:1px solid var(--line);}\n  table.items input,table.items select{width:100%; padding:7px 8px; border:1px solid var(--line); border-radius:6px; background:#fbfaff;}\n  table.items .num{text-align:right;}\n  table.items tfoot td{font-weight:700; background:#f6f3fc;}\n  .row-del{background:none; border:none; color:#c0392b; font-size:16px; cursor:pointer; font-weight:800;}\n  .add-row-btn{margin-top:8px; background:#efe9fa; color:var(--purple); border:1px dashed var(--purple);\n    padding:7px 14px; border-radius:7px; font-weight:700; cursor:pointer;}\n\n  /* ---------- TOTALS ---------- */\n  .totals{margin-top:12px; margin-left:auto; width:320px; max-width:100%;}\n  .totals .trow{display:flex; justify-content:space-between; padding:6px 4px; border-bottom:1px dashed var(--line);}\n  .totals .trow.grand{font-size:16px; font-weight:800; color:var(--purple); border-bottom:2px solid var(--orange);}\n  .totals .trow input{width:90px; text-align:right; padding:4px 6px; border:1px solid var(--line); border-radius:6px;}\n  .words{margin-top:10px; font-size:12px; font-style:italic; color:var(--muted);}\n\n  /* ---------- MODAL ---------- */\n  .modal-back{position:fixed; inset:0; background:rgba(30,15,60,.55); display:none; align-items:center;\n    justify-content:center; z-index:100; padding:16px;}\n  .modal-back.open{display:flex;}\n  .modal{background:#fff; border-radius:14px; width:560px; max-width:100%; max-height:92vh; overflow:auto; padding:20px;}\n  .modal h3{color:var(--purple); margin-bottom:14px; font-size:16px;}\n  .modal .m-actions{display:flex; justify-content:flex-end; gap:8px; margin-top:14px;}\n\n  /* ---------- TOAST ---------- */\n  #toast{position:fixed; bottom:22px; left:50%; transform:translateX(-50%); background:var(--purple); color:#fff;\n    padding:11px 22px; border-radius:30px; font-size:13px; font-weight:700; display:none; z-index:200;\n    box-shadow:0 6px 20px rgba(0,0,0,.3);}\n  #toast.err{background:#c0392b;}\n  #toast.show{display:block; animation:pop .25s;}\n  @keyframes pop{from{opacity:0; transform:translate(-50%,10px);} to{opacity:1; transform:translate(-50%,0);}}\n\n  /* ---------- PRINT AREA (single unified layout: TAX INVOICE / QUOTATION / DELIVERY NOTE) ---------- */\n  #printArea{display:none;}\n  .p-head{display:flex; justify-content:space-between; align-items:flex-start; border-bottom:3px solid var(--purple); padding-bottom:10px;}\n  .p-head img{height:82px; border:none; box-shadow:none; background:transparent;}\n  .p-co{text-align:right; font-size:11px; line-height:1.5;}\n  #pCoAddress{white-space:pre-line;}\n  #pBillToAddress{white-space:pre-line;}\n  .p-co .co-name{font-size:20px; font-weight:800; letter-spacing:2px; line-height:1.1;}\n  .p-title{background:var(--purple); color:#fff; text-align:center; font-weight:800; letter-spacing:4px;\n    padding:7px; margin:12px 0; font-size:15px;}\n  .p-meta{display:flex; gap:16px; margin-bottom:12px;}\n  .p-meta > div{flex:1;}\n  .p-box{border:1px solid #999; border-radius:6px; padding:8px 10px; min-height:96px;}\n  .p-box h4{font-size:10px; letter-spacing:1px; color:var(--purple); margin-bottom:5px; text-transform:uppercase;}\n  .p-meta table{width:100%; border-collapse:collapse; font-size:11px;}\n  .p-meta td{padding:2px 4px; vertical-align:top;}\n  .p-meta td:first-child{font-weight:700; white-space:nowrap; width:1%;}\n  table.p-items{width:100%; border-collapse:collapse; margin-top:4px;}\n  table.p-items th{background:var(--purple); color:#fff; padding:7px 8px; font-size:11px; border:1px solid var(--purple); text-align:left;}\n  table.p-items th.r{text-align:right;}\n  table.p-items td{border:1px solid #999; padding:7px 8px; font-size:12px;}\n  table.p-items td.r{text-align:right;}\n  table.p-items tfoot td{font-weight:700; background:#f1edf8;}\n  .p-bottom{display:flex; gap:16px; margin-top:14px;}\n  .p-bank{flex:1; border:1px solid #999; border-radius:6px; padding:9px 11px; font-size:11px; line-height:1.7;}\n  .p-bank h4{color:var(--purple); font-size:11px; letter-spacing:1px; margin-bottom:4px;}\n  .p-sign{flex:1; display:flex; flex-direction:column; justify-content:flex-end; text-align:center; font-size:11px;}\n  .p-sign .sig-line{border-top:1px solid #111; margin-top:44px; padding-top:4px; font-weight:700;}\n  .p-words{margin-top:12px; font-size:12px; font-style:italic;}\n  .p-terms{margin-top:12px; border:1px solid #999; border-radius:6px; padding:9px 11px;\n    font-size:10.5px; line-height:1.65; white-space:pre-line;}\n  .p-terms h4{color:var(--purple); font-size:11px; letter-spacing:1px; margin-bottom:4px;}\n  .p-foot{margin-top:14px; text-align:center; font-size:10px; color:#666; border-top:1px solid #ccc; padding-top:6px;}\n  @page{size:A4; margin:12mm;}\n  .p-bottom,.p-terms,.p-meta,.p-head,table.p-items tr{page-break-inside:avoid;}\n\n  @media print{\n    body{background:#fff; padding:0;}\n    .no-print{display:none !important;}\n    #toast{display:none !important;}\n    #printArea{display:block !important; color:#111; font-size:12px; padding:10px;}\n  }\n\n  /* ---------- DOC TYPE TABS ---------- */\n  .doc-tabs{display:flex; gap:6px; background:rgba(255,255,255,.12); padding:4px; border-radius:10px;}\n  .doc-tab{border:none; background:transparent; color:#fff; padding:8px 14px; border-radius:7px;\n    font-weight:700; font-size:12px; cursor:pointer; letter-spacing:.5px; opacity:.8; font-family:inherit;}\n  .doc-tab:hover{opacity:1;}\n  .doc-tab.active{background:#fff; color:var(--purple); opacity:1;}\n\n  /* ---------- QUOTE / DELIVERY NOTE EDITOR BITS ---------- */\n  .btn-bar{margin-top:12px; display:flex; gap:8px; flex-wrap:wrap;}\n  .line-item-row{display:grid; grid-template-columns:2fr 1fr .8fr 1fr .8fr .8fr auto; gap:6px;\n    align-items:center; margin-bottom:6px; padding:8px; background:#f7fafc; border-radius:7px; border:1px solid var(--line);}\n  .line-item-row.dn{grid-template-columns:2.4fr 1fr .8fr 1.2fr 1.4fr auto;}\n  .line-item-row input,.line-item-row select{padding:7px 8px; border:1px solid var(--line); border-radius:6px;\n    font-size:12px; font-family:inherit; background:#fff; width:100%;}\n  .li-total{font-weight:700; color:var(--purple); text-align:right; font-size:12px; padding:0 4px;}\n  .logo-upload-area{display:flex; align-items:center; gap:12px; margin-bottom:12px; padding:12px;\n    background:#f0f4f8; border-radius:8px; border:2px dashed var(--orange);}\n  .logo-preview-box{width:70px; height:70px; border:1px solid var(--line); border-radius:6px; display:flex;\n    align-items:center; justify-content:center; background:#fff; overflow:hidden; flex-shrink:0;}\n  .logo-preview-box img{max-width:100%; max-height:100%; object-fit:contain;}\n  .logo-placeholder{font-size:20px; color:var(--muted);}\n</style>\n<meta name=\"theme-color\" content=\"#4b2683\">\n<style>\n/* Accounting tab — uses the reference's own tokens (--purple, --orange, --line, --muted). */\n.acc-bar{display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-bottom:14px;}\n.acc-tab{border:1px solid var(--line); background:#fff; color:var(--purple); padding:8px 14px; border-radius:8px;\n  font-weight:700; font-size:12px; cursor:pointer; font-family:inherit;}\n.acc-tab.active{background:var(--purple); color:#fff; border-color:var(--purple);}\n.acc-sp{flex:1;}\n.acc-cur{font-size:11px; font-weight:700; color:var(--muted); display:flex; align-items:center; gap:6px;}\n.acc-cur select{padding:6px 8px; border:1px solid var(--line); border-radius:6px; background:#fff;}\n.acc-scroll{overflow-x:auto;}\n.kpis{display:grid; grid-template-columns:repeat(5,1fr); gap:10px;}\n.kpi{background:#f6f3fc; border:1px solid var(--line); border-radius:10px; padding:10px 12px;}\n.kpi span{display:block; font-size:11px; color:var(--muted); font-weight:700; margin-bottom:2px;}\n.kpi b{font-size:17px; color:var(--purple);}\n.st{display:inline-block; font-size:10px; font-weight:800; padding:2px 8px; border-radius:20px; background:#efe9fa; color:var(--purple);}\n.st-Paid{background:#e3f6ea; color:#1e7a3c;}\n.st-Partial{background:#fff0e0; color:#b85c00;}\n.st-Unpaid{background:#fde8e6; color:#c0392b;}\n.st-Overpaid{background:#e6efff; color:#1a56b0;}\n.jl{display:grid; grid-template-columns:1fr 90px 90px; gap:6px; font-size:12px; padding:2px 0; color:var(--ink);}\n.jrow{display:grid; grid-template-columns:2fr 1fr 1fr; gap:6px; margin-bottom:6px;}\n.jrow select,.jrow input{padding:7px 8px; border:1px solid var(--line); border-radius:6px; background:#fbfaff; width:100%;}\n.rpt-sec{margin-top:16px;}\ntable.rpt{width:100%; border-collapse:collapse;}\ntable.rpt th{background:var(--purple); color:#fff; font-size:11px; padding:8px; text-align:left;}\ntable.rpt td{padding:6px 8px; border-bottom:1px solid var(--line);}\ntable.rpt .num,table.items .num{text-align:right;}\ntable.rpt tr.sub td{background:#f6f3fc; font-weight:700; color:var(--purple); font-size:12px;}\ntable.rpt tr.tot td{font-weight:800; border-top:2px solid var(--orange);}\n\n/* ---------- MOBILE (phones) — desktop layout is unchanged ---------- */\n@media(max-width:640px){\n  .topbar{padding:8px 10px; gap:8px;}\n  .topbar img{height:40px;}\n  .doc-tabs{width:100%; flex-wrap:wrap;}\n  .doc-tab{flex:1 1 44%; white-space:nowrap; padding:8px 6px; font-size:11px;}\n  #branchSelect{min-width:0; width:100%;}\n  .branch-wrap{width:100%; flex-wrap:wrap;}\n  .wrap{padding:10px;}\n  .wrap>*{min-width:0;}   /* let wide tables scroll inside their card instead of stretching the page */\n  .card{overflow-x:auto; padding:12px;}\n  table.items{min-width:620px;}\n  .line-item-row,.line-item-row.dn{grid-template-columns:1fr 1fr;}\n  .line-item-row>:first-child{grid-column:1/-1;}\n  .totals{width:100%;}\n  .kpis{grid-template-columns:1fr 1fr;}\n  .modal{padding:14px;}\n  .jrow{grid-template-columns:1fr 1fr;}\n  .jrow select{grid-column:1/-1;}\n}\n\n/* printing the Accounting tab (Ctrl+P / Print button) shows the reports instead of a blank invoice */\n@media print{\n  html:not([data-print]) body.mode-acc #viewAcc.no-print{display:block !important;}\n  html:not([data-print]) body.mode-acc #printArea{display:none !important;}\n  html:not([data-print]) body.mode-acc .acc-bar,html:not([data-print]) body.mode-acc .btn-bar,html:not([data-print]) body.mode-acc .topbar{display:none !important;}\n}\n\n/* sources + receipt summary */\n.st-voucher{background:#e8f6f3; color:#12756b;}\n.st-payment{background:#fff0e0; color:#b85c00;}\n.st-manual{background:#efe9fa; color:var(--purple);}\n.rc-sum{display:grid; grid-template-columns:1fr 1fr; gap:8px; margin:12px 0;}\n.rc-sum div{background:#f6f3fc; border:1px solid var(--line); border-radius:8px; padding:8px 10px; font-size:11px; color:var(--muted); font-weight:700;}\n.rc-sum b{display:block; font-size:14px; color:var(--purple); margin-top:2px; word-break:break-word;}\n\n/* jobs */\n.st-job{background:#efe9fa; color:var(--purple);}\n.st-agentpay{background:#e6efff; color:#1a56b0;}\n.neg{color:#c0392b;} .pos{color:#1e7a3c;}\n#jTable{min-width:900px;}\n#jTable input.num{text-align:right;}\n@media(max-width:640px){ #viewJob .card{overflow-x:auto;} }\n</style>\n</head>\n<body class=\"mode-invoice\">\n\n<!-- ================= TOP BAR ================= -->\n<div class=\"topbar no-print\">\n  <img src=\"data:image/jpeg;base64,\" alt=\"Well Reach Logistics\">\n  <div class=\"tb-title\">\n    <h1>TAX INVOICE PANEL</h1>\n    <span>WELL REACH LOGISTICS &nbsp;|&nbsp; INDIA &amp; BAHRAIN</span>\n  </div>\n  <button class=\"btn btn-ghost\" id=\"signOutBtn\" style=\"display:none\" onclick=\"signOut()\">Sign out</button>\n  <div class=\"doc-tabs\">\n    <button class=\"doc-tab active\" id=\"tabInvoice\" onclick=\"switchDoc('invoice')\">&#128441; TAX INVOICE</button>\n    <button class=\"doc-tab\" id=\"tabQuote\" onclick=\"switchDoc('quote')\">&#128196; QUOTATION</button>\n    <button class=\"doc-tab\" id=\"tabDN\" onclick=\"switchDoc('dn')\">&#128666; DELIVERY NOTE</button>\n    <button class=\"doc-tab\" id=\"tabAcc\" onclick=\"switchDoc('acc')\">&#128202; ACCOUNTING</button>\n  </div>\n  <span id=\"invoiceControls\" style=\"display:contents\"><div class=\"tb-controls\">\n    <div class=\"branch-wrap\">\n      <label>BRANCH</label>\n      <select id=\"branchSelect\" onchange=\"onBranchChange()\"></select>\n      <button class=\"btn btn-orange\" onclick=\"openBranchModal()\" title=\"Add / edit branches\">＋ Branch</button>\n    </div>\n    <button class=\"btn btn-ghost\" onclick=\"liveSync()\">⟳ Live Sync</button>\n    <span class=\"sync-info\" id=\"syncInfo\">—</span>\n    <button class=\"btn btn-ghost\" onclick=\"openLoadInvoiceModal()\" title=\"Load a previously saved invoice from the system to edit it\">📂 Load Invoice</button>\n    <button class=\"btn btn-ghost\" onclick=\"newInvoice()\" title=\"Clear invoice fields and start a fresh invoice (company & bank details stay)\">🔄 New Invoice</button>\n    <button class=\"btn btn-white\" onclick=\"saveInvoice()\">💾 Save to Cloud</button>\n    <button class=\"btn btn-orange\" onclick=\"printCurrentDoc()\">🖨 Print</button>\n  </div></span>\n</div>\n\n<div class=\"wrap no-print\" id=\"viewInvoice\">\n  <!-- ================= LEFT : MAIN PANEL ================= -->\n  <div>\n    <div class=\"card\">\n      <h3>Invoice Details</h3>\n      <div class=\"grid3\">\n        <div class=\"fld\"><label>Invoice No (auto — editable)</label><input id=\"invNo\" style=\"background:#efe9fa;font-weight:700;color:var(--purple);\"></div>\n        <div class=\"fld\"><label>Invoice Date</label><input id=\"invDate\" type=\"date\"></div>\n        <div class=\"fld\"><label>Currency</label>\n          <select id=\"currency\" onchange=\"computeTotals()\">\n            <option value=\"INR\">₹ INR — Indian Rupee</option>\n            <option value=\"BHD\">BHD — Bahraini Dinar</option>\n            <option value=\"USD\">$ USD — US Dollar</option>\n            <option value=\"EUR\">€ EUR — Euro</option>\n            <option value=\"GBP\">£ GBP — British Pound</option>\n            <option value=\"AED\">AED — UAE Dirham</option>\n            <option value=\"SAR\">SAR — Saudi Riyal</option>\n            <option value=\"QAR\">QAR — Qatari Riyal</option>\n            <option value=\"KWD\">KWD — Kuwaiti Dinar</option>\n            <option value=\"OMR\">OMR — Omani Rial</option>\n            <option value=\"JPY\">¥ JPY — Japanese Yen</option>\n            <option value=\"CNY\">¥ CNY — Chinese Yuan</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Place of Supply</label><input id=\"placeSupply\" placeholder=\"Editable\"></div>\n        <div class=\"fld\"><label>Mode / Terms</label><input id=\"terms\" placeholder=\"e.g. Immediate / 30 days\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>AWB / BL No</label><input id=\"awbNo\" placeholder=\"Air Waybill / Bill of Lading No\"></div>\n        <div class=\"fld\"><label>Commodity</label><input id=\"commodity\" placeholder=\"e.g. General Cargo\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Gross Weight (KG)</label><input id=\"grossWeight\" placeholder=\"e.g. 1250\"></div>\n        <div class=\"fld\"><label>Volume (CBM)</label><input id=\"volume\" placeholder=\"e.g. 4.5\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Shipment Mode</label>\n          <select id=\"shipMode\">\n            <option value=\"\">— Select —</option>\n            <option>Air Freight</option>\n            <option>Road Freight</option>\n            <option>Sea Freight</option>\n            <option>FCL</option>\n            <option>LCL</option>\n          </select></div>\n        <div class=\"fld\"><label>Shipment Terms (Incoterms)</label>\n          <select id=\"shipTerms\">\n            <option value=\"\">— Select —</option>\n            <option>EXW — Ex Works</option>\n            <option>FCA — Free Carrier</option>\n            <option>FAS — Free Alongside Ship</option>\n            <option>FOB — Free On Board</option>\n            <option>CFR — Cost and Freight</option>\n            <option>CIF — Cost, Insurance and Freight</option>\n            <option>CPT — Carriage Paid To</option>\n            <option>CIP — Carriage and Insurance Paid To</option>\n            <option>DAP — Delivered At Place</option>\n            <option>DPU — Delivered at Place Unloaded</option>\n            <option>DDP — Delivered Duty Paid</option>\n          </select></div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Bill To (Customer)</h3>\n      <div class=\"grid2\">\n        <div class=\"fld\"><label>Customer / Company Name</label><input id=\"billTo\" placeholder=\"Customer name\"></div>\n        <div class=\"fld\"><label id=\"billTaxLabel\">GSTIN / VAT No</label><input id=\"billToTaxNo\" placeholder=\"Customer tax no\"></div>\n      </div>\n      <div class=\"fld\" style=\"margin-top:10px;\"><label>Customer Address</label><textarea id=\"billToAddress\" placeholder=\"Full address\"></textarea></div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Items / Services</h3>\n      <table class=\"items\">\n        <thead><tr>\n          <th style=\"width:36px;\">#</th><th>Description of Goods / Services</th>\n          <th style=\"width:80px;\">Qty / No</th><th style=\"width:110px;\">Unit</th>\n          <th style=\"width:130px;\">Rate</th>\n          <th style=\"width:130px;\">Amount</th><th style=\"width:36px;\"></th>\n        </tr></thead>\n        <tbody id=\"itemsBody\"></tbody>\n      </table>\n      <button class=\"add-row-btn\" onclick=\"addItemRow()\">＋ Add Item Row</button>\n\n      <div class=\"totals\">\n        <div class=\"trow\"><span>Subtotal</span><b id=\"subTotal\">0.00</b></div>\n        <div class=\"trow\" id=\"taxRow1Wrap\"><span id=\"taxRow1Label\">CGST</span>\n          <span><input id=\"taxRate1\" type=\"number\" step=\"0.01\" value=\"9\" oninput=\"computeTotals()\"> % = <b id=\"taxAmt1\">0.00</b></span></div>\n        <div class=\"trow\" id=\"taxRow2Wrap\"><span id=\"taxRow2Label\">SGST</span>\n          <span><input id=\"taxRate2\" type=\"number\" step=\"0.01\" value=\"9\" oninput=\"computeTotals()\"> % = <b id=\"taxAmt2\">0.00</b></span></div>\n        <div class=\"trow grand\"><span>GRAND TOTAL</span><b id=\"grandTotal\" style=\"color:var(--orange);\">0.00</b></div>\n      </div>\n      <div class=\"words\" id=\"amountWords\">—</div>\n    </div>\n  </div>\n\n  <!-- ================= RIGHT : COMPANY / BRANCH PANEL ================= -->\n  <div>\n    <div class=\"card\">\n      <h3>Company / Branch Details</h3>\n      <div style=\"margin-bottom:10px;\"><span class=\"country-badge\" id=\"countryBadge\">INDIA</span></div>\n      <div class=\"fld\" style=\"margin-bottom:10px;\"><label>Company Name</label>\n        <input id=\"coName\" value=\"Well Reach Logistics\" placeholder=\"Printed on the TAX INVOICE\"></div>\n      <div class=\"fld\" style=\"margin-bottom:10px;\"><label>Branch Address</label>\n        <textarea id=\"coAddress\" placeholder=\"Enter branch address\"></textarea></div>\n      <div class=\"grid2\" style=\"margin-bottom:10px;\">\n        <div class=\"fld\"><label>Phone</label><input id=\"coPhone\"></div>\n        <div class=\"fld\"><label>Email</label><input id=\"coEmail\"></div>\n      </div>\n      <div class=\"fld\" style=\"margin-bottom:10px;\"><label id=\"coTaxLabel\">GST Registration No</label>\n        <input id=\"coTaxNo\" placeholder=\"Enter registration no\"></div>\n      <div class=\"autosave-note\">✔ Company &amp; bank details are <b>auto-saved</b> to the cloud when you change them.</div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Bank Details (Branch)</h3>\n      <div class=\"fld\" style=\"margin-bottom:10px;\"><label>Bank Name</label><input id=\"bankName\"></div>\n      <div class=\"fld\" style=\"margin-bottom:10px;\"><label>Account Name</label><input id=\"accountName\" value=\"Well Reach Logistics\"></div>\n      <div class=\"grid2\" style=\"margin-bottom:10px;\">\n        <div class=\"fld\"><label>Account No</label><input id=\"accountNo\"></div>\n        <div class=\"fld\"><label>IBAN</label><input id=\"iban\" placeholder=\"e.g. BH.. / international\"></div>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"fld\"><label>IFSC / SWIFT</label><input id=\"ifsc\"></div>\n        <div class=\"fld\"><label>Bank Branch</label><input id=\"bankBranch\"></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ================= BRANCH MODAL ================= -->\n<div class=\"modal-back no-print\" id=\"branchModal\">\n  <div class=\"modal\">\n    <h3 id=\"branchModalTitle\">Add New Branch</h3>\n    <div class=\"grid2\">\n      <div class=\"fld\"><label>Country</label>\n        <select id=\"mCountry\" onchange=\"mCountryChange()\"><option value=\"India\">India</option><option value=\"Bahrain\">Bahrain</option></select></div>\n      <div class=\"fld\"><label>Branch Name</label><input id=\"mName\" placeholder=\"e.g. Kochi Branch\"></div>\n    </div>\n    <div class=\"fld\" style=\"margin-top:10px;\"><label>Company Name</label><input id=\"mCoName\" value=\"Well Reach Logistics\" placeholder=\"Printed on the TAX INVOICE\"></div>\n    <div class=\"fld\" style=\"margin-top:10px;\"><label>Branch Address</label><textarea id=\"mAddress\"></textarea></div>\n    <div class=\"grid2\" style=\"margin-top:10px;\">\n      <div class=\"fld\"><label>Phone</label><input id=\"mPhone\"></div>\n      <div class=\"fld\"><label>Email</label><input id=\"mEmail\"></div>\n    </div>\n    <div class=\"fld\" style=\"margin-top:10px;\"><label id=\"mTaxLabel\">GST Registration No</label><input id=\"mTaxNo\"></div>\n    <div class=\"fld\" style=\"margin-top:10px;\"><label>Bank Name</label><input id=\"mBankName\"></div>\n    <div class=\"grid2\" style=\"margin-top:10px;\">\n      <div class=\"fld\"><label>Account Name</label><input id=\"mAccountName\" value=\"Well Reach Logistics\"></div>\n      <div class=\"fld\"><label>Account No</label><input id=\"mAccountNo\"></div>\n    </div>\n    <div class=\"grid3\" style=\"margin-top:10px;\">\n      <div class=\"fld\"><label>IBAN</label><input id=\"mIban\"></div>\n      <div class=\"fld\"><label>IFSC / SWIFT</label><input id=\"mIfsc\"></div>\n      <div class=\"fld\"><label>Bank Branch</label><input id=\"mBankBranch\"></div>\n    </div>\n    <div class=\"m-actions\">\n      <button class=\"btn\" id=\"mDeleteBtn\" style=\"background:#c0392b;color:#fff;margin-right:auto;display:none;\" onclick=\"deleteBranchFromModal()\">🗑 Delete Branch</button>\n      <button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"closeBranchModal()\">Cancel</button>\n      <button class=\"btn btn-orange\" onclick=\"saveBranchFromModal()\">💾 Save Branch</button>\n    </div>\n  </div>\n</div>\n\n<!-- ================= LOAD INVOICE MODAL ================= -->\n<div class=\"modal-back no-print\" id=\"loadInvoiceModal\">\n  <div class=\"modal\" style=\"width:640px;\">\n    <h3>Load Invoice from Cloud &mdash; Edit</h3>\n    <div class=\"fld\" style=\"margin-bottom:10px;\">\n      <input id=\"loadSearch\" placeholder=\"🔍 Search by invoice no, customer or date…\" oninput=\"filterInvoicePicker()\">\n    </div>\n    <div id=\"loadInvoiceList\" style=\"max-height:50vh; overflow:auto;\"></div>\n    <div class=\"m-actions\">\n      <button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"closeLoadInvoiceModal()\">Cancel</button>\n    </div>\n  </div>\n</div>\n\n<!-- ==================== QUOTATION VIEW (editor) ==================== -->\n<div id=\"viewQuote\" class=\"no-print\" style=\"display:none;\">\n  <div class=\"wrap\" style=\"grid-template-columns:1fr; max-width:1000px;\">\n    <div class=\"card\">\n      <h3>Quotation &mdash; Company &amp; Customer</h3>\n      <div class=\"logo-upload-area\">\n        <div class=\"logo-preview-box\">\n          <img id=\"logoPreview\" src=\"\" alt=\"Logo\" style=\"display:none;\">\n          <span id=\"logoPlaceholder\" class=\"logo-placeholder\">&#127970;</span>\n        </div>\n        <div style=\"flex:1;\">\n          <label style=\"font-weight:700; color:var(--purple); font-size:13px; display:block; margin-bottom:4px;\">Company Logo</label>\n          <input type=\"file\" id=\"logoUpload\" accept=\"image/*\" onchange=\"qHandleLogoUpload(event)\" style=\"font-size:12px;\">\n          <p style=\"font-size:11px; color:var(--muted); margin-top:2px;\">PNG/JPG/SVG (max 2MB). Logo appears in the printed quotation.</p>\n        </div>\n        <button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"qRemoveLogo()\">Remove</button>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"fld\"><label>Company Name</label><input id=\"compName\" value=\"WELL REACH LOGISTICS\"></div>\n        <div class=\"fld\"><label>Website</label><input id=\"compWeb\" value=\"www.wellreachlogistics.com\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Company Address</label><textarea id=\"compAddr\">#206, Finteer Center, Building #85, Road 1802, Manama, Kingdom of Bahrain</textarea></div>\n        <div class=\"fld\"><label>CR Number</label><input id=\"compCR\" value=\"193163-1\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Quote To (Customer Name)</label><input id=\"custName\"></div>\n        <div class=\"fld\"><label>Customer Mobile</label><input id=\"custMobile\"></div>\n      </div>\n      <div class=\"fld\" style=\"margin-top:10px;\"><label>Customer Address</label><textarea id=\"custAddr\"></textarea></div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Quotation Details</h3>\n      <div class=\"grid3\">\n        <div class=\"fld\"><label>Quotation Ref# (Auto &mdash; type to override)</label><input id=\"quotNo\" style=\"background:#efe9fa; font-weight:700; color:var(--purple);\"></div>\n        <div class=\"fld\"><label>Quotation Date</label><input id=\"quotDate\" type=\"date\"></div>\n        <div class=\"fld\"><label>BL / AWB No</label><input id=\"blNo\"></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>No. of Pieces</label><input id=\"numPcs\" type=\"number\"></div>\n        <div class=\"fld\"><label>Origin</label><input id=\"shipOrigin\"></div>\n        <div class=\"fld\"><label>Destination</label><input id=\"shipDest\"></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Gross Weight (KG)</label><input id=\"grossWt\" type=\"number\"></div>\n        <div class=\"fld\"><label>Chargeable Weight (KG)</label><input id=\"chargeWt\" type=\"number\"></div>\n        <div class=\"fld\"><label>Commodity</label><input id=\"qCommodity\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Shipment Mode</label>\n          <select id=\"qShipMode\">\n            <option value=\"\">— Select —</option>\n            <option>Air Freight</option>\n            <option>Road Freight</option>\n            <option>Sea Freight</option>\n            <option>FCL</option>\n            <option>LCL</option>\n          </select></div>\n        <div class=\"fld\"><label>Shipment Terms (Incoterms)</label>\n          <select id=\"qShipTerms\">\n            <option value=\"\">— Select —</option>\n            <option>EXW — Ex Works</option>\n            <option>FCA — Free Carrier</option>\n            <option>FAS — Free Alongside Ship</option>\n            <option>FOB — Free On Board</option>\n            <option>CFR — Cost and Freight</option>\n            <option>CIF — Cost, Insurance and Freight</option>\n            <option>CPT — Carriage Paid To</option>\n            <option>CIP — Carriage and Insurance Paid To</option>\n            <option>DAP — Delivered At Place</option>\n            <option>DPU — Delivered at Place Unloaded</option>\n            <option>DDP — Delivered Duty Paid</option>\n          </select></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Currency</label>\n          <select id=\"invCurrency\" onchange=\"quoteRefreshTotals()\">\n            <option value=\"BHD\" selected>BHD</option><option value=\"USD\">USD</option><option value=\"EURO\">EURO</option>\n            <option value=\"AED\">AED</option><option value=\"SAR\">SAR</option><option value=\"INR\">INR</option>\n          </select></div>\n        <div class=\"fld\"><label>VAT % (per line default)</label><input id=\"vatRate\" type=\"number\" value=\"0\" step=\"0.1\"></div>\n        <div class=\"fld\"><label>&nbsp;</label><span></span></div>\n      </div>\n      <div class=\"fld\" style=\"margin-top:10px;\"><label>Terms &amp; Conditions</label><textarea id=\"termsConditions\" placeholder=\"Enter terms and conditions specific to this quotation...\" style=\"min-height:60px;\"></textarea></div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Quotation Line Items</h3>\n      <div id=\"lineItemsEditor\"></div>\n      <div class=\"totals\" style=\"margin-top:14px;\">\n        <div class=\"trow\"><span>Subtotal</span><b id=\"qSubTotal\">0.00</b></div>\n        <div class=\"trow\"><span>VAT Amount</span><b id=\"qVatAmount\">0.00</b></div>\n        <div class=\"trow grand\"><span>GRAND TOTAL</span><b id=\"qGrandTotal\" style=\"color:var(--orange);\">0.00</b></div>\n      </div>\n      <div class=\"btn-bar\">\n        <button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"quoteAddItem()\">&#10133; Add Line Item</button>\n        <button class=\"btn btn-orange\" onclick=\"saveQuoteSheet()\">&#128190; Save to Cloud</button>\n        <button class=\"btn btn-orange\" onclick=\"printCurrentDoc()\">&#128424; Print / Save as PDF</button>\n        <button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"resetQuote()\">&#128260; Reset All</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ==================== DELIVERY NOTE VIEW (editor) ==================== -->\n<div id=\"viewDN\" class=\"no-print\" style=\"display:none;\">\n  <div class=\"wrap\" style=\"grid-template-columns:1fr; max-width:1000px;\">\n    <div class=\"card\">\n      <h3>Delivery Note &mdash; Company &amp; Customer</h3>\n      <div class=\"grid2\">\n        <div class=\"fld\"><label>Company Name</label><input id=\"dCompName\" value=\"WELL REACH LOGISTICS\"></div>\n        <div class=\"fld\"><label>Website</label><input id=\"dCompWeb\" value=\"www.wellreachlogistics.com\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Company Address</label><textarea id=\"dCompAddr\">#206, Finteer Center, Building #85, Road 1802, Manama, Kingdom of Bahrain</textarea></div>\n        <div class=\"fld\"><label>CR Number</label><input id=\"dCR\" value=\"193163-1\"></div>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Deliver To (Customer Name)</label><input id=\"dCustName\"></div>\n        <div class=\"fld\"><label>Customer Mobile</label><input id=\"dCustMobile\"></div>\n      </div>\n      <div class=\"fld\" style=\"margin-top:10px;\"><label>Customer Address</label><textarea id=\"dCustAddr\"></textarea></div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Delivery Details</h3>\n      <div class=\"grid3\">\n        <div class=\"fld\"><label>Delivery Note Ref# (Auto &mdash; type to override)</label><input id=\"dDnNo\" style=\"background:#efe9fa; font-weight:700; color:var(--purple);\"></div>\n        <div class=\"fld\"><label>Delivery Date</label><input id=\"dDnDate\" type=\"date\"></div>\n        <div class=\"fld\"><label>BL / AWB No</label><input id=\"dBlNo\"></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>No. of Pieces</label><input id=\"dNumPcs\" type=\"number\"></div>\n        <div class=\"fld\"><label>Origin</label><input id=\"dOrigin\"></div>\n        <div class=\"fld\"><label>Destination</label><input id=\"dDest\"></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Gross Weight (KG)</label><input id=\"dGrossWt\" type=\"number\"></div>\n        <div class=\"fld\"><label>Chargeable Weight (KG)</label><input id=\"dChargeWt\" type=\"number\"></div>\n        <div class=\"fld\"><label>Commodity</label><input id=\"dCommodity\"></div>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:10px;\">\n        <div class=\"fld\"><label>Delivered By</label><input id=\"dDeliveredBy\"></div>\n        <div class=\"fld\"><label>Truck No</label><input id=\"dTruckNo\"></div>\n        <div class=\"fld\"><label>Driver Name</label><input id=\"dDriverName\"></div>\n      </div>\n      <div class=\"fld\" style=\"margin-top:10px;\"><label>Terms &amp; Conditions</label><textarea id=\"dTerms\" placeholder=\"Enter terms and conditions specific to this delivery note...\" style=\"min-height:60px;\"></textarea></div>\n    </div>\n\n    <div class=\"card\">\n      <h3>Delivery Line Items</h3>\n      <div id=\"dItemsEditor\"></div>\n      <div class=\"btn-bar\">\n        <button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"dnAddItem()\">&#10133; Add Line Item</button>\n        <button class=\"btn btn-orange\" onclick=\"saveDNSheet()\">&#128190; Save to Cloud</button>\n        <button class=\"btn btn-orange\" onclick=\"printCurrentDoc()\">&#128424; Print / Save as PDF</button>\n        <button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"resetDN()\">&#128260; Reset All</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div id=\"viewAcc\" class=\"no-print\" style=\"display:none;\"></div>\n\n<!-- ==================== UNIFIED PRINT AREA ====================\n     One skeleton drives ALL THREE documents (TAX INVOICE / QUOTATION / DELIVERY NOTE)\n     so every printed output follows the exact same layout & styling.            -->\n<div id=\"printArea\">\n  <div class=\"p-head\">\n    <img id=\"pLogo\" src=\"\" alt=\"Well Reach Logistics\">\n    <div class=\"p-co\">\n      <div class=\"co-name\" id=\"pCoName\"></div>\n      <div id=\"pCoAddress\"></div>\n      <div id=\"pCoPhoneEmail\"></div>\n      <div id=\"pCoTax\"></div>\n    </div>\n  </div>\n  <div class=\"p-title\" id=\"pTitle\">TAX INVOICE</div>\n  <div class=\"p-meta\">\n    <div class=\"p-box\">\n      <h4 id=\"pPartyLabel\">Bill To</h4>\n      <b id=\"pBillTo\"></b>\n      <div id=\"pBillToAddress\"></div>\n      <div id=\"pBillToTax\"></div>\n    </div>\n    <div><table id=\"pMetaTable\"></table></div>\n  </div>\n  <table class=\"p-items\">\n    <thead id=\"pItemsHead\"></thead>\n    <tbody id=\"pItemsBody\"></tbody>\n    <tfoot id=\"pItemsFoot\"></tfoot>\n  </table>\n  <div class=\"p-words\" id=\"pWordsWrap\"><b>Amount in words:</b> <span id=\"pWords\"></span></div>\n  <div class=\"p-terms\" id=\"pTermsWrap\" style=\"display:none;\"><h4>TERMS &amp; CONDITIONS</h4><div id=\"pTerms\"></div></div>\n  <div class=\"p-bottom\">\n    <div class=\"p-bank\">\n      <h4>BANK DETAILS</h4>\n      <div id=\"pBank\"></div>\n    </div>\n    <div class=\"p-sign\">\n      <div>For <b id=\"pCoNameSign\"></b></div>\n      <div class=\"sig-line\">Authorised Signatory</div>\n    </div>\n  </div>\n  <div class=\"p-foot\">This is a computer generated <span id=\"pDocName\">TAX INVOICE</span> — <span id=\"pCoNameFoot\">Well Reach Logistics</span> | Thank you for your business.</div>\n</div>\n\n<div id=\"toast\"></div>\n\n<script src=\"core.js\"></script>\n<script>\n\n/* Replacement for Google Apps Script's google.script.run.\n   - Real Apps Script (google.script.run exists): left untouched.\n   - Served by server.js (POST api/ping answers): every call goes to POST api/<function>.\n   - Anywhere else (opened from a file, static hosting, preview): the same API runs in the browser, saved in localStorage. */\n(function () {\n  if (window.google && window.google.script && window.google.script.run) return;\n\n  var mem = null;\n  var local = WRLCore.create({\n    load: function () { try { var t = localStorage.getItem('wrl_suite_db_v1'); if (t) return JSON.parse(t); } catch (e) {} return mem; },\n    save: function (d) { mem = d; try { localStorage.setItem('wrl_suite_db_v1', JSON.stringify(d)); } catch (e) {} }\n  });\n\n  var post = function (name, arg) {\n    return fetch('api/' + name, { method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ arg: arg === undefined ? null : arg }) }).then(function (r) { return r.json(); });\n  };\n  var modeP = /^https?:$/.test(location.protocol)\n    ? post('ping').then(function (j) { return j && j.ok ? 'server' : 'local'; }).catch(function () { return 'local'; })\n    : Promise.resolve('local');\n\n  function localCall(name, arg) {\n    try {\n      if (!Object.prototype.hasOwnProperty.call(local, name)) throw new Error('Unknown function: ' + name);\n      var res = local[name](arg === null ? undefined : arg);\n      return { ok: true, result: res === undefined ? undefined : JSON.parse(JSON.stringify(res)) };\n    } catch (e) { return { ok: false, error: e.message }; }\n  }\n\n  function runner(ok, fail) {\n    var base = {\n      withSuccessHandler: function (f) { return runner(f, fail); },\n      withFailureHandler: function (f) { return runner(ok, f); }\n    };\n    return new Proxy(base, {\n      get: function (t, name) {\n        if (name in t) return t[name];\n        return function (arg) {\n          modeP.then(function (mode) { return mode === 'server' ? post(String(name), arg) : localCall(String(name), arg); })\n            .catch(function (e) { return { ok: false, error: e.message || 'Network error' }; })\n            .then(function (j) { if (j.ok) { if (ok) ok(j.result); } else if (j.auth) { location.reload(); } else if (fail) fail({ message: j.error }); });\n        };\n      }\n    });\n  }\n  window.google = { script: { run: runner() } };\n\n  window.addEventListener('load', function () {\n    modeP.then(function (m) {\n      if (m === 'local') setTimeout(function () { try { toast('ℹ Offline mode — data is saved in this browser'); } catch (e) {} }, 3200);\n    });\n  });\n})();\n\n</script>\n<script>\n/* =====================================================\n   STATE\n===================================================== */\nvar branches = [];\nvar currentBranch = null;\nvar autoSaveTimer = null;\nvar lastAutoInvNo = '';   /* last auto-generated number shown in the field */\nvar editingInvoiceNo = ''; /* when set, Save updates this existing invoice instead of appending */\nvar invoiceListCache = [];\nvar LOGO_SRC = document.querySelector('.topbar img') ? document.querySelector('.topbar img').src : '';\n\n/* =====================================================\n   INIT\n===================================================== */\nwindow.onload = function() {\n  document.getElementById('invDate').valueAsDate = new Date();\n  addItemRow();\n  run('getInitialData', function(res) {\n    branches = res.branches;\n    renderBranchSelect();\n    if (branches.length) selectBranch(branches[0].name);\n    liveSync();\n  });\n};\n\n/* =====================================================\n   SERVER HELPER\n===================================================== */\nfunction run(fn, ok, arg) {\n  var r = google.script.run.withFailureHandler(function(e){ toast('⚠ ' + e.message, true); });\n  if (ok) r = r.withSuccessHandler(ok);\n  r[fn](arg);\n}\n\n/* =====================================================\n   TOAST\n===================================================== */\nfunction toast(msg, isErr) {\n  var t = document.getElementById('toast');\n  t.textContent = msg;\n  t.className = 'show' + (isErr ? ' err' : '');\n  clearTimeout(t._h);\n  t._h = setTimeout(function(){ t.className = ''; }, 2800);\n}\n\n/* =====================================================\n   BRANCH SELECTOR\n===================================================== */\nfunction renderBranchSelect() {\n  var sel = document.getElementById('branchSelect');\n  sel.innerHTML = '';\n  branches.forEach(function(b) {\n    var o = document.createElement('option');\n    o.value = b.name; o.textContent = b.name + ' (' + b.country + ')';\n    sel.appendChild(o);\n  });\n}\nfunction onBranchChange() { selectBranch(document.getElementById('branchSelect').value); }\n\nfunction selectBranch(name) {\n  currentBranch = branches.filter(function(b){ return b.name === name; })[0] || null;\n  if (!currentBranch) return;\n  document.getElementById('branchSelect').value = name;\n  fillCompanyPanel(currentBranch);\n  applyTaxMode();\n  computeTotals();\n}\nfunction fillCompanyPanel(b) {\n  setv('coName', b.companyName || 'Well Reach Logistics');\n  setv('coAddress', b.address); setv('coPhone', b.phone); setv('coEmail', b.email);\n  setv('coTaxNo', b.taxNo); setv('coTaxLabel', (b.taxLabel || (b.country === 'Bahrain' ? 'VAT Registration' : 'GST Registration')) + ' No');\n  setv('bankName', b.bankName); setv('accountName', b.accountName);\n  setv('accountNo', b.accountNo); setv('iban', b.iban); setv('ifsc', b.ifsc); setv('bankBranch', b.bankBranch);\n  document.getElementById('countryBadge').textContent = b.country.toUpperCase();\n  document.getElementById('currency').value = (b.country === 'Bahrain') ? 'BHD' : 'INR';\n  document.getElementById('billTaxLabel').textContent = (b.country === 'Bahrain' ? 'VAT' : 'GSTIN') + ' No';\n}\n\n/* Auto-save company/bank details whenever edited */\n['coName','coAddress','coPhone','coEmail','coTaxNo','bankName','accountName','accountNo','iban','ifsc','bankBranch']\n.forEach(function(id){\n  document.addEventListener('change', function(e){ if (e.target && e.target.id === id) scheduleBranchAutoSave(); });\n});\nfunction scheduleBranchAutoSave() {\n  clearTimeout(autoSaveTimer);\n  autoSaveTimer = setTimeout(function() {\n    if (!currentBranch) return;\n    var b = collectBranchFromPanel();\n    run('saveBranch', function(list){ branches = list; renderBranchSelect(); toast('✔ Branch details auto-saved'); }, b);\n  }, 700);\n}\nfunction collectBranchFromPanel() {\n  return {\n    name: currentBranch.name, country: currentBranch.country, companyName: gv('coName'),\n    address: gv('coAddress'), phone: gv('coPhone'), email: gv('coEmail'),\n    taxLabel: currentBranch.country === 'Bahrain' ? 'VAT Registration' : 'GST Registration',\n    taxNo: gv('coTaxNo'),\n    bankName: gv('bankName'), accountName: gv('accountName'), accountNo: gv('accountNo'),\n    iban: gv('iban'), ifsc: gv('ifsc'), bankBranch: gv('bankBranch')\n  };\n}\n\n/* =====================================================\n   BRANCH MODAL (Add / Edit)\n===================================================== */\nfunction openBranchModal() {\n  var editing = document.getElementById('branchSelect').value;\n  var b = branches.filter(function(x){ return x.name === editing; })[0];\n  document.getElementById('branchModalTitle').textContent = b ? 'Edit Branch — ' + b.name : 'Add New Branch';\n  setv('mCountry', b ? b.country : 'India');\n  setv('mName', b ? b.name : '');\n  setv('mCoName', b ? (b.companyName || 'Well Reach Logistics') : 'Well Reach Logistics');\n  setv('mAddress', b ? b.address : ''); setv('mPhone', b ? b.phone : ''); setv('mEmail', b ? b.email : '');\n  setv('mTaxNo', b ? b.taxNo : '');\n  setv('mBankName', b ? b.bankName : ''); setv('mAccountName', b ? b.accountName : 'Well Reach Logistics');\n  setv('mAccountNo', b ? b.accountNo : ''); setv('mIban', b ? b.iban : '');\n  setv('mIfsc', b ? b.ifsc : ''); setv('mBankBranch', b ? b.bankBranch : '');\n  mCountryChange();\n  document.getElementById('mDeleteBtn').style.display = b ? '' : 'none';\n  document.getElementById('branchModal').classList.add('open');\n}\n\n/* Delete the branch currently open in the modal */\nfunction deleteBranchFromModal() {\n  var name = gv('mName').trim();\n  if (!name) { closeBranchModal(); return; }\n  if (!confirm('Delete branch \"' + name + '\" permanently from the list?')) return;\n  run('deleteBranch', function(list) {\n    branches = list; renderBranchSelect();\n    if (branches.length) selectBranch(branches[0].name);\n    closeBranchModal();\n    toast('🗑 Branch \"' + name + '\" deleted');\n  }, name);\n}\nfunction closeBranchModal() { document.getElementById('branchModal').classList.remove('open'); }\nfunction mCountryChange() {\n  var c = gv('mCountry');\n  document.getElementById('mTaxLabel').textContent = (c === 'Bahrain' ? 'VAT Registration' : 'GST Registration') + ' No';\n}\nfunction saveBranchFromModal() {\n  var name = gv('mName').trim();\n  if (!name) { toast('⚠ Branch name is required', true); return; }\n  var b = {\n    name: name, country: gv('mCountry'), companyName: gv('mCoName') || 'Well Reach Logistics',\n    address: gv('mAddress'), phone: gv('mPhone'), email: gv('mEmail'),\n    taxLabel: gv('mCountry') === 'Bahrain' ? 'VAT Registration' : 'GST Registration', taxNo: gv('mTaxNo'),\n    bankName: gv('mBankName'), accountName: gv('mAccountName'), accountNo: gv('mAccountNo'),\n    iban: gv('mIban'), ifsc: gv('mIfsc'), bankBranch: gv('mBankBranch')\n  };\n  run('saveBranch', function(list) {\n    branches = list; renderBranchSelect(); selectBranch(name);\n    closeBranchModal(); toast('✔ Branch \"' + name + '\" saved');\n  }, b);\n}\n\n/* =====================================================\n   TAX MODE : India = CGST+SGST, Bahrain = VAT\n===================================================== */\nfunction applyTaxMode() {\n  var india = currentBranch && currentBranch.country === 'India';\n  if (india) {\n    document.getElementById('taxRow1Label').textContent = 'CGST';\n    document.getElementById('taxRow2Label').textContent = 'SGST';\n    document.getElementById('taxRow2Wrap').style.display = '';\n    document.getElementById('taxRate1').value = 9;\n    document.getElementById('taxRate2').value = 9;\n  } else {\n    document.getElementById('taxRow1Label').textContent = 'VAT';\n    document.getElementById('taxRow2Wrap').style.display = 'none';\n    document.getElementById('taxRate1').value = 10;\n  }\n}\n\n/* =====================================================\n   ITEMS\n===================================================== */\nfunction addItemRow() {\n  var tb = document.getElementById('itemsBody');\n  var tr = document.createElement('tr');\n  tr.innerHTML =\n    '<td class=\"idx\"></td>' +\n    '<td><input class=\"i-desc\" placeholder=\"Description\"></td>' +\n    '<td><input class=\"i-qty num\" type=\"number\" min=\"0\" step=\"any\" value=\"1\" oninput=\"computeTotals()\"></td>' +\n    '<td><select class=\"i-unit\" onchange=\"computeTotals()\">' +\n      '<option>Pcs</option><option>Palette</option><option>Boxes</option><option>Package</option><option>Days</option><option>Services</option></select></td>' +\n    '<td><input class=\"i-rate num\" type=\"number\" min=\"0\" step=\"any\" value=\"0\" oninput=\"computeTotals()\"></td>' +\n    '<td class=\"i-amt num\" style=\"padding-top:12px;font-weight:700;\">0.00</td>' +\n    '<td><button class=\"row-del\" onclick=\"this.closest(\\'tr\\').remove();computeTotals();\">✕</button></td>';\n  tb.appendChild(tr);\n  renumber();\n  computeTotals();\n}\nfunction renumber() {\n  var rows = document.querySelectorAll('#itemsBody tr');\n  rows.forEach(function(r, i){ r.querySelector('.idx').textContent = i + 1; });\n}\nfunction readItems() {\n  var out = [];\n  document.querySelectorAll('#itemsBody tr').forEach(function(r) {\n    var d = r.querySelector('.i-desc').value.trim();\n    var q = parseFloat(r.querySelector('.i-qty').value) || 0;\n    var u = r.querySelector('.i-unit').value;\n    var rt = parseFloat(r.querySelector('.i-rate').value) || 0;\n    if (d || q || rt) out.push({ desc: d, qty: q, unit: u, rate: rt, amount: round2(q * rt) });\n  });\n  return out;\n}\n\n/* =====================================================\n   TOTALS\n===================================================== */\nfunction computeTotals() {\n  var cur = document.getElementById('currency').value;\n  var items = readItems();\n  var sub = items.reduce(function(s, it){ return s + it.amount; }, 0);\n  var india = currentBranch && currentBranch.country === 'India';\n  var r1 = parseFloat(document.getElementById('taxRate1').value) || 0;\n  var a1 = round2(sub * r1 / 100);\n  var r2 = india ? (parseFloat(document.getElementById('taxRate2').value) || 0) : 0;\n  var a2 = india ? round2(sub * r2 / 100) : 0;\n  var grand = round2(sub + a1 + a2);\n\n  document.querySelectorAll('#itemsBody tr').forEach(function(r) {\n    var q = parseFloat(r.querySelector('.i-qty').value) || 0;\n    var rt = parseFloat(r.querySelector('.i-rate').value) || 0;\n    r.querySelector('.i-amt').textContent = fmt(round2(q * rt), cur);\n  });\n  document.getElementById('subTotal').textContent = fmt(sub, cur);\n  document.getElementById('taxAmt1').textContent = fmt(a1, cur);\n  document.getElementById('taxAmt2').textContent = fmt(a2, cur);\n  document.getElementById('grandTotal').textContent = fmt(grand, cur);\n  var words = numberToWords(grand, cur);\n  document.getElementById('amountWords').textContent = words ? words + ' Only' : '—';\n  renumber();\n  return { items: items, subtotal: sub, taxType: india ? 'CGST+SGST' : 'VAT',\n           taxRate: india ? (r1 + r2) : r1, taxAmount: round2(a1 + a2), grandTotal: grand, words: words };\n}\n\n/* =====================================================\n   LOAD INVOICE FROM SHEET (edit existing)\n===================================================== */\nfunction openLoadInvoiceModal() {\n  document.getElementById('loadSearch').value = '';\n  document.getElementById('loadInvoiceModal').classList.add('open');\n  document.getElementById('loadInvoiceList').innerHTML =\n    '<div style=\"padding:18px;text-align:center;color:var(--muted);\">Loading invoices from cloud…</div>';\n  run('getInvoiceList', function(list) {\n    invoiceListCache = list || [];\n    renderInvoicePickerRows(invoiceListCache);\n  });\n}\nfunction closeLoadInvoiceModal() { document.getElementById('loadInvoiceModal').classList.remove('open'); }\n\nfunction renderInvoicePickerRows(list) {\n  var c = document.getElementById('loadInvoiceList');\n  if (!list.length) {\n    c.innerHTML = '<div style=\"padding:18px;text-align:center;color:var(--muted);\">No invoices found in the system.</div>';\n    return;\n  }\n  var h = '';\n  list.forEach(function(v) {\n    h += '<div onclick=\"loadInvoiceIntoPanel(\\'' + v.invoiceNo.replace(/'/g, \"\\\\'\") + '\\')\" ' +\n      'style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;' +\n      'border:1px solid var(--line);border-radius:8px;margin-bottom:8px;cursor:pointer;background:#fff;\" ' +\n      'onmouseover=\"this.style.background=\\'#efe9fa\\'\" onmouseout=\"this.style.background=\\'#fff\\'\">' +\n      '<div><b style=\"color:var(--purple);\">' + esc(v.invoiceNo) + '</b> ' +\n      '<span style=\"color:var(--muted);font-size:12px;\">' + esc(v.invoiceDate) + '</span>' +\n      '<div style=\"font-size:12px;color:var(--muted);\">' + esc(v.billTo || '—') + '</div></div>' +\n      '<div style=\"font-weight:700;white-space:nowrap;\">' + esc(String(v.grandTotal)) + ' ' + esc(v.currency) + '</div></div>';\n  });\n  c.innerHTML = h;\n}\n\nfunction filterInvoicePicker() {\n  var q = document.getElementById('loadSearch').value.toLowerCase();\n  renderInvoicePickerRows(invoiceListCache.filter(function(v) {\n    return (v.invoiceNo + ' ' + (v.billTo || '') + ' ' + v.invoiceDate).toLowerCase().indexOf(q) !== -1;\n  }));\n}\n\nfunction loadInvoiceIntoPanel(no) {\n  toast('Loading ' + no + '…');\n  run('getInvoice', function(d) {\n    /* Branch first (fills company/bank + tax mode + currency), then the\n       invoice's own snapshot overwrites the panel fields. */\n    if (d.branch) {\n      var b = branches.filter(function(x) { return x.name === d.branch; })[0];\n      if (b) selectBranch(b.name);\n    }\n    setv('coName', d.companyName); setv('coAddress', d.companyAddress);\n    setv('coPhone', d.companyPhone); setv('coEmail', d.companyEmail); setv('coTaxNo', d.companyTaxNo);\n    setv('bankName', d.bankName); setv('accountName', d.accountName); setv('accountNo', d.accountNo);\n    setv('iban', d.iban); setv('ifsc', d.ifsc); setv('bankBranch', d.bankBranch);\n    if (d.currency) document.getElementById('currency').value = d.currency;\n    if (d.branchCountry) document.getElementById('countryBadge').textContent = d.branchCountry.toUpperCase();\n\n    editingInvoiceNo = d.invoiceNo;\n    setv('invNo', d.invoiceNo); lastAutoInvNo = d.invoiceNo;\n    document.getElementById('invDate').value = d.invoiceDate || new Date().toISOString().split('T')[0];\n    setv('billTo', d.billTo); setv('billToAddress', d.billToAddress); setv('billToTaxNo', d.billToTaxNo);\n    setv('placeSupply', d.placeOfSupply); setv('terms', d.terms);\n    setv('awbNo', d.awbNo); setv('commodity', d.commodity);\n    setv('grossWeight', d.grossWeight); setv('volume', d.volume);\n    setv('shipMode', d.shipMode); setv('shipTerms', d.shipTerms);\n\n    /* Items */\n    document.getElementById('itemsBody').innerHTML = '';\n    var its = (d.items && d.items.length) ? d.items : [{ desc:'', qty:1, unit:'Pcs', rate:0 }];\n    its.forEach(function(it) {\n      addItemRow();\n      var rows = document.querySelectorAll('#itemsBody tr');\n      var r = rows[rows.length - 1];\n      r.querySelector('.i-desc').value = it.desc || '';\n      r.querySelector('.i-qty').value = (it.qty !== undefined && it.qty !== null && it.qty !== '') ? it.qty : 1;\n      r.querySelector('.i-unit').value = it.unit || 'Pcs';\n      r.querySelector('.i-rate').value = it.rate || 0;\n    });\n\n    /* Tax rates stored on the invoice */\n    applyTaxMode();\n    var india = currentBranch && currentBranch.country === 'India';\n    var tr = parseFloat(d.taxRate) || 0;\n    if (india) {\n      document.getElementById('taxRate1').value = tr / 2;\n      document.getElementById('taxRate2').value = tr / 2;\n    } else {\n      document.getElementById('taxRate1').value = tr;\n    }\n    computeTotals();\n\n    closeLoadInvoiceModal();\n    document.getElementById('syncInfo').textContent = '✏ Editing ' + d.invoiceNo;\n    toast('✏ Loaded ' + d.invoiceNo + ' — edit & press Save to update the same row');\n  }, no);\n}\n\n/* =====================================================\n   NEW INVOICE — clears only the invoice-side fields.\n   Company / branch / bank details are preserved.\n===================================================== */\nfunction newInvoice() {\n  if (!confirm('Start a new invoice?\\nInvoice fields (customer, items, shipment details) will be cleared.\\nCompany & bank details stay unchanged.')) return;\n  editingInvoiceNo = '';\n  ['placeSupply','terms','awbNo','commodity','grossWeight','volume',\n   'billTo','billToAddress','billToTaxNo','shipMode','shipTerms'].forEach(function(id) {\n    document.getElementById(id).value = '';\n  });\n  document.getElementById('invDate').valueAsDate = new Date();\n  document.getElementById('itemsBody').innerHTML = '';\n  addItemRow();\n  applyTaxMode();\n  computeTotals();\n  /* Refresh the auto invoice number from the sheet */\n  run('getNextInvoiceNo', function(no) {\n    document.getElementById('invNo').value = no;\n    lastAutoInvNo = no;\n    document.getElementById('syncInfo').textContent = '—';\n    toast('🔄 New invoice ready — ' + no);\n  });\n}\n\n/* =====================================================\n   SAVE INVOICE TO SHEET\n===================================================== */\nfunction saveInvoice() {\n  var t = computeTotals();\n  if (!t.items.length) { toast('⚠ Add at least one item', true); return; }\n  if (!gv('billTo').trim()) { toast('⚠ Enter Bill To customer name', true); return; }\n  var payload = {\n    invoiceNo: gv('invNo'), invoiceDate: gv('invDate'),\n    branchName: currentBranch.name, branchCountry: currentBranch.country,\n    companyName: gv('coName'), companyAddress: gv('coAddress'),\n    companyPhone: gv('coPhone'), companyEmail: gv('coEmail'), companyTaxNo: gv('coTaxNo'),\n    billTo: gv('billTo'), billToAddress: gv('billToAddress'), billToTaxNo: gv('billToTaxNo'),\n    placeOfSupply: gv('placeSupply'), terms: gv('terms'), currency: document.getElementById('currency').value,\n    awbNo: gv('awbNo'), commodity: gv('commodity'), grossWeight: gv('grossWeight'), volume: gv('volume'),\n    items: t.items, subtotal: t.subtotal, taxType: t.taxType, taxRate: t.taxRate,\n    shipMode: gv('shipMode'), shipTerms: gv('shipTerms'),\n    taxAmount: t.taxAmount, grandTotal: t.grandTotal, amountWords: t.words,\n    bankName: gv('bankName'), accountName: gv('accountName'), accountNo: gv('accountNo'),\n    iban: gv('iban'), ifsc: gv('ifsc'), bankBranch: gv('bankBranch'),\n    branch: collectBranchFromPanel()\n  };\n  if (editingInvoiceNo) {\n    payload.originalInvoiceNo = editingInvoiceNo;\n    toast('Updating ' + editingInvoiceNo + ' in Cloud…');\n    run('updateInvoice', function(res) {\n      toast('✔ Updated — ' + res.invoiceNo + ' (same sheet row, no duplicate)');\n    }, payload);\n    return;\n  }\n  toast('Saving to Cloud…');\n  run('saveInvoice', function(res) {\n    toast('✔ Saved — ' + res.invoiceNo + ' → Cloud');\n    document.getElementById('invNo').value = res.nextInvoiceNo;\n    lastAutoInvNo = res.nextInvoiceNo;\n  }, payload);\n}\n\n/* =====================================================\n   LIVE SYNC\n===================================================== */\nfunction liveSync() {\n  var name = currentBranch ? currentBranch.name : '';\n  run('syncData', function(res) {\n    branches = res.branches;\n    renderBranchSelect();\n    if (currentBranch) selectBranch(currentBranch.name);\n    else if (branches.length) selectBranch(branches[0].name);\n    /* Only refresh the number if the user has not typed a custom one */\n    var curNo = gv('invNo');\n    if (!curNo || curNo === lastAutoInvNo) {\n      document.getElementById('invNo').value = res.nextInvoiceNo;\n      lastAutoInvNo = res.nextInvoiceNo;\n    }\n    var d = new Date(res.syncedAt);\n    var last = res.lastInvoice ? (' | Last: ' + res.lastInvoice.invoiceNo + ' (' + res.lastInvoice.billTo + ')') : '';\n    document.getElementById('syncInfo').textContent = 'Synced ' + d.toLocaleTimeString() + last;\n    toast('⟳ Live sync complete');\n  }, name);\n}\n\n/* =====================================================\n   UNIFIED PRINT ENGINE — one skeleton, three documents.\n   Quotation & Delivery Note outputs follow the TAX INVOICE\n   layout exactly (same header, title band, meta boxes,\n   purple items table, totals, words, bank, signatory, footer).\n===================================================== */\nfunction printIfFilled(elId, value, prefix) {\n  var el = document.getElementById(elId);\n  if (!el) return;\n  if (value && String(value).trim()) {\n    el.textContent = (prefix || '') + value;\n    el.style.display = '';\n  } else {\n    el.textContent = '';\n    el.style.display = 'none';\n  }\n}\n\n/* Rebuild the right-hand meta table from [[label, value, bold?], ...]\n   Empty rows are skipped, so nothing blank is ever printed. */\nfunction fillMeta(rows) {\n  var h = '';\n  rows.forEach(function(r) {\n    var v = (r[1] === undefined || r[1] === null) ? '' : String(r[1]).trim();\n    if (!v) return;\n    h += '<tr><td>' + esc(r[0]) + '</td><td>' + (r[2] ? '<b>' + esc(v) + '</b>' : esc(v)) + '</td></tr>';\n  });\n  document.getElementById('pMetaTable').innerHTML = h;\n}\n\n/* Bank block: uses the current branch's bank details when present,\n   otherwise falls back to the standard Bahrain account. */\nfunction fillPrintBank(source) {\n  var b = currentBranch || {};\n  var branchHasBank = b && (b.bankName || b.accountNo || b.iban || b.ifsc);\n  var rows;\n  if (source === 'branch' || (source === 'auto' && branchHasBank)) {\n    rows = [\n      ['Bank', b.bankName], ['Account Name', b.accountName], ['Account No', b.accountNo],\n      ['IBAN', b.iban], ['IFSC / SWIFT', b.ifsc], ['Branch', b.bankBranch]\n    ];\n  } else {\n    rows = [\n      ['Beneficiary', 'WELL REACH LOGISTICS SERVICES WLL'],\n      ['A/c No', '396818100100'],\n      ['Bank', 'AL SALAM BANK'],\n      ['IBAN', 'BH04ALSA00396818100100'],\n      ['Swift', 'ALSABHBM']\n    ];\n  }\n  document.getElementById('pBank').innerHTML =\n    rows.filter(function(x){ return String(x[1] || '').trim(); })\n        .map(function(x){ return '<b>' + x[0] + ':</b> ' + esc(x[1]); }).join('<br>') || '—';\n}\n\n/* Fill the shared print skeleton. opts:\n   logo, title, partyLabel, companyName, companyAddress,\n   companyLine2, companyLine3, partyName, partyAddress, partyExtra,\n   meta (rows), itemsHead (html), itemsBody (html), itemsFoot (html),\n   words ('' hides the block), bankSource ('branch' | 'auto')          */\nfunction buildPrintShell(opts) {\n  document.getElementById('pLogo').src = opts.logo || LOGO_SRC;\n  setTxt('pTitle', opts.title);\n  setTxt('pDocName', opts.title);\n  setTxt('pPartyLabel', opts.partyLabel);\n  document.getElementById('pCoName').innerHTML = coloredNameHtml(opts.companyName);\n  printIfFilled('pCoAddress', opts.companyAddress);\n  printIfFilled('pCoPhoneEmail', opts.companyLine2);\n  printIfFilled('pCoTax', opts.companyLine3);\n  setTxt('pCoNameSign', opts.companyName);\n  setTxt('pCoNameFoot', opts.companyName);\n  setTxt('pBillTo', opts.partyName);\n  printIfFilled('pBillToAddress', opts.partyAddress);\n  printIfFilled('pBillToTax', opts.partyExtra);\n  fillMeta(opts.meta);\n  document.getElementById('pItemsHead').innerHTML = opts.itemsHead;\n  document.getElementById('pItemsBody').innerHTML = opts.itemsBody;\n  document.getElementById('pItemsFoot').innerHTML = opts.itemsFoot || '';\n  var ww = document.getElementById('pWordsWrap');\n  if (opts.words) { setTxt('pWords', opts.words); ww.style.display = ''; }\n  else { setTxt('pWords', ''); ww.style.display = 'none'; }\n  var tw = document.getElementById('pTermsWrap');\n  if (opts.terms && String(opts.terms).trim()) {\n    document.getElementById('pTerms').textContent = opts.terms;\n    tw.style.display = '';\n  } else {\n    document.getElementById('pTerms').textContent = '';\n    tw.style.display = 'none';\n  }\n  fillPrintBank(opts.bankSource);\n}\n\n/* ---------- TAX INVOICE print ---------- */\nfunction buildInvoicePrint() {\n  var t = computeTotals();\n  var cur = document.getElementById('currency').value;\n  var branchCountry = currentBranch ? currentBranch.country : 'India';\n  var india = branchCountry === 'India';\n  var r1 = parseFloat(document.getElementById('taxRate1').value) || 0;\n  var a1 = round2(t.subtotal * r1 / 100);\n\n  var body = '';\n  t.items.forEach(function(it, i) {\n    body += '<tr><td>' + (i + 1) + '</td><td>' + esc(it.desc) + '</td>' +\n      '<td class=\"r\">' + it.qty + '</td><td>' + esc(it.unit || '') + '</td>' +\n      '<td class=\"r\">' + fmt(it.rate, cur) + '</td><td class=\"r\">' + fmt(it.amount, cur) + '</td></tr>';\n  });\n\n  var foot = '<tr><td colspan=\"5\" class=\"r\">Subtotal</td><td class=\"r\">' + fmt(t.subtotal, cur) + '</td></tr>';\n  foot += '<tr><td colspan=\"5\" class=\"r\">' + (india ? 'CGST' : 'VAT') + ' @ ' + r1 + '%</td><td class=\"r\">' + fmt(a1, cur) + '</td></tr>';\n  if (india) {\n    var r2 = parseFloat(document.getElementById('taxRate2').value) || 0;\n    foot += '<tr><td colspan=\"5\" class=\"r\">SGST @ ' + r2 + '%</td><td class=\"r\">' + fmt(round2(t.subtotal * r2 / 100), cur) + '</td></tr>';\n  }\n  foot += '<tr><td colspan=\"5\" class=\"r\" style=\"font-size:14px;\">GRAND TOTAL</td>' +\n          '<td class=\"r\" style=\"color:var(--orange);font-size:14px;\">' + fmt(t.grandTotal, cur) + '</td></tr>';\n\n  buildPrintShell({\n    logo: LOGO_SRC,\n    title: 'TAX INVOICE',\n    partyLabel: 'Bill To',\n    companyName: gv('coName'),\n    companyAddress: gv('coAddress'),\n    companyLine2: [gv('coPhone'), gv('coEmail')].filter(Boolean).join(' | '),\n    companyLine3: gv('coTaxNo') ? ((branchCountry === 'Bahrain' ? 'VAT Reg No: ' : 'GST Reg No: ') + gv('coTaxNo')) : '',\n    partyName: gv('billTo'),\n    partyAddress: gv('billToAddress'),\n    partyExtra: gv('billToTaxNo') ? ((branchCountry === 'Bahrain' ? 'VAT No: ' : 'GSTIN: ') + gv('billToTaxNo')) : '',\n    meta: [\n      ['Invoice No:', gv('invNo'), true],\n      ['Invoice Date:', gv('invDate')],\n      ['Place of Supply:', gv('placeSupply')],\n      ['Terms:', gv('terms')],\n      ['AWB / BL No:', gv('awbNo')],\n      ['Commodity:', gv('commodity')],\n      ['Gross Weight:', gv('grossWeight') ? gv('grossWeight') + ' KG' : ''],\n      ['Volume:', gv('volume') ? gv('volume') + ' CBM' : ''],\n      ['Shipment Mode:', gv('shipMode')],\n      ['Shipment Terms:', gv('shipTerms')]\n    ],\n    itemsHead: '<tr><th style=\"width:36px;\">#</th><th>Description of Goods / Services</th>' +\n      '<th style=\"width:60px;\" class=\"r\">Qty / No</th><th style=\"width:80px;\">Unit</th>' +\n      '<th style=\"width:110px;\" class=\"r\">Rate</th><th style=\"width:120px;\" class=\"r\">Amount</th></tr>',\n    itemsBody: body,\n    itemsFoot: foot,\n    words: t.words ? t.words + ' Only' : '',\n    bankSource: 'branch'\n  });\n}\n\n/* Scale the print skeleton down so TAX INVOICE / QUOTATION / DELIVERY NOTE\n   always fit on ONE A4 page, whatever the content volume. */\nfunction fitPrintToOnePage() {\n  var pa = document.getElementById('printArea');\n  pa.style.zoom = '';\n  /* A4 @ 96dpi = 1123px tall; 12mm top+bottom margins ≈ 90px */\n  var availH = 1030;\n  var h = pa.offsetHeight || 0;\n  if (h > availH) pa.style.zoom = Math.max(0.45, availH / h);\n}\n\n/* Builds the correct print layout for the ACTIVE document and then prints.\n   Called directly by every print button — does NOT rely on window.onbeforeprint,\n   which does not fire reliably inside the Apps Script iframe and was causing\n   the wrong document (e.g. Delivery Note) to be printed for the Tax Invoice. */\nfunction printCurrentDoc() {\n  try {\n    if (currentDoc === 'quote') buildQuotePrint();\n    else if (currentDoc === 'dn') buildDNPrint();\n    else buildInvoicePrint();\n  } catch (err) {\n    toast('⚠ Print error: ' + err.message, true);\n    return;\n  }\n  fitPrintToOnePage();\n  window.print();\n}\nwindow.onafterprint = function() {\n  document.getElementById('printArea').style.zoom = '';\n};\nwindow.onbeforeprint = function() {\n  if (currentDoc === 'quote') buildQuotePrint();\n  else if (currentDoc === 'dn') buildDNPrint();\n  else buildInvoicePrint();\n};\n\n/* =====================================================\n   DOCUMENT TYPE SWITCH  (Invoice / Quotation / Delivery Note)\n===================================================== */\nvar currentDoc = 'invoice';\nfunction switchDoc(t) {\n  currentDoc = t;\n  document.body.className = 'mode-' + t;\n  document.getElementById('tabInvoice').classList.toggle('active', t === 'invoice');\n  document.getElementById('tabQuote').classList.toggle('active', t === 'quote');\n  document.getElementById('tabDN').classList.toggle('active', t === 'dn');\n  document.getElementById('viewInvoice').style.display = t === 'invoice' ? '' : 'none';\n  document.getElementById('viewQuote').style.display  = t === 'quote'  ? '' : 'none';\n  document.getElementById('viewDN').style.display     = t === 'dn'     ? '' : 'none';\n  document.getElementById('invoiceControls').style.display = t === 'invoice' ? 'contents' : 'none';\n}\n\n/* =====================================================\n   QUOTATION — editor logic (print output = invoice layout)\n===================================================== */\nvar lineItems = [{ desc: '', hsCode: '', qty: 1, price: 0, vat: 0 }];\nvar logoDataUrl = '';\nvar QUOTE_CURR_NAMES = { BHD:'Bahraini Dinars', USD:'US Dollars', EURO:'Euros', AED:'UAE Dirhams', SAR:'Saudi Riyals', INR:'Indian Rupees' };\nvar QUOTE_NUM_WORDS = { 0:'Zero',1:'One',2:'Two',3:'Three',4:'Four',5:'Five',6:'Six',7:'Seven',8:'Eight',9:'Nine',10:'Ten',\n  11:'Eleven',12:'Twelve',13:'Thirteen',14:'Fourteen',15:'Fifteen',16:'Sixteen',17:'Seventeen',18:'Eighteen',19:'Nineteen',20:'Twenty',\n  30:'Thirty',40:'Forty',50:'Fifty',60:'Sixty',70:'Seventy',80:'Eighty',90:'Ninety' };\n\nfunction genQuoteRef() {\n  var now = new Date();\n  var ymd = now.getFullYear() + ('0' + (now.getMonth() + 1)).slice(-2) + ('0' + now.getDate()).slice(-2);\n  var rand = Math.floor(1000 + Math.random() * 9000);\n  document.getElementById('quotNo').value = 'WRL-BH-' + ymd + '-' + rand;\n}\n\nfunction qHandleLogoUpload(event) {\n  var file = event.target.files[0];\n  if (!file) return;\n  if (file.size > 2 * 1024 * 1024) { toast('Logo too large. Max 2MB.', true); return; }\n  var reader = new FileReader();\n  reader.onload = function(e) {\n    logoDataUrl = e.target.result;\n    document.getElementById('logoPreview').src = logoDataUrl;\n    document.getElementById('logoPreview').style.display = 'block';\n    document.getElementById('logoPlaceholder').style.display = 'none';\n  };\n  reader.readAsDataURL(file);\n}\nfunction qRemoveLogo() {\n  logoDataUrl = '';\n  document.getElementById('logoUpload').value = '';\n  document.getElementById('logoPreview').style.display = 'none';\n  document.getElementById('logoPlaceholder').style.display = 'block';\n}\n\nfunction renderQuoteItems() {\n  var c = document.getElementById('lineItemsEditor');\n  var h = '';\n  lineItems.forEach(function(item, idx) {\n    h += '<div class=\"line-item-row\">' +\n      '<input type=\"text\" placeholder=\"Description\" value=\"' + esc(item.desc) + '\" onchange=\"quoteUpdateItem(' + idx + ',\\'desc\\',this.value)\">' +\n      '<input type=\"text\" placeholder=\"HS Code\" value=\"' + esc(item.hsCode) + '\" onchange=\"quoteUpdateItem(' + idx + ',\\'hsCode\\',this.value)\">' +\n      '<input type=\"number\" placeholder=\"Qty\" value=\"' + item.qty + '\" min=\"1\" onchange=\"quoteUpdateItem(' + idx + ',\\'qty\\',this.value)\">' +\n      '<input type=\"number\" placeholder=\"Price\" value=\"' + item.price.toFixed(2) + '\" step=\"0.01\" onchange=\"quoteUpdateItem(' + idx + ',\\'price\\',this.value)\">' +\n      '<input type=\"number\" placeholder=\"VAT%\" value=\"' + item.vat + '\" step=\"0.1\" onchange=\"quoteUpdateItem(' + idx + ',\\'vat\\',this.value)\">' +\n      '<span class=\"li-total\" id=\"editorTotal_' + idx + '\">' + (item.qty * item.price).toFixed(2) + '</span>' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--line); padding:5px 10px; font-size:11px;\" onclick=\"quoteRemoveItem(' + idx + ')\">&#10060;</button>' +\n      '</div>';\n  });\n  c.innerHTML = h;\n  quoteRefreshTotals();\n}\nfunction quoteUpdateItem(idx, field, value) {\n  if (field === 'qty' || field === 'price' || field === 'vat') lineItems[idx][field] = parseFloat(value) || 0;\n  else lineItems[idx][field] = value;\n  var et = document.getElementById('editorTotal_' + idx);\n  if (et) et.textContent = (lineItems[idx].qty * lineItems[idx].price).toFixed(2);\n  quoteRefreshTotals();\n}\nfunction quoteAddItem() { lineItems.push({ desc:'', hsCode:'', qty:1, price:0, vat: parseFloat(document.getElementById('vatRate').value) || 0 }); renderQuoteItems(); }\nfunction quoteRemoveItem(idx) { lineItems.splice(idx, 1); renderQuoteItems(); }\n\nfunction quoteComputeTotals() {\n  var sub = 0, vat = 0;\n  lineItems.forEach(function(it) { sub += it.qty * it.price; vat += it.qty * it.price * (it.vat / 100); });\n  return { subtotal: round2(sub), vatAmount: round2(vat), grandTotal: round2(sub + vat) };\n}\n\n/* Live totals shown under the quotation line items editor */\nfunction quoteRefreshTotals() {\n  var t = quoteComputeTotals();\n  var cur = document.getElementById('invCurrency').value;\n  document.getElementById('qSubTotal').textContent = t.subtotal.toFixed(2) + ' ' + cur;\n  document.getElementById('qVatAmount').textContent = t.vatAmount.toFixed(2) + ' ' + cur;\n  document.getElementById('qGrandTotal').textContent = t.grandTotal.toFixed(2) + ' ' + cur;\n}\n\n/* ---------- QUOTATION print — same layout as TAX INVOICE ---------- */\nfunction buildQuotePrint() {\n  var cur = document.getElementById('invCurrency').value;\n  var t = quoteComputeTotals();\n\n  var body = '';\n  lineItems.forEach(function(it, i) {\n    body += '<tr><td>' + (i + 1) + '</td>' +\n      '<td>' + esc(it.desc) + '</td>' +\n      '<td>' + esc(it.hsCode) + '</td>' +\n      '<td>' + esc(cur) + '</td>' +\n      '<td class=\"r\">' + it.qty + '</td>' +\n      '<td class=\"r\">' + it.price.toFixed(2) + '</td>' +\n      '<td class=\"r\">' + it.vat.toFixed(1) + '%</td>' +\n      '<td class=\"r\" style=\"font-weight:700;\">' + (it.qty * it.price).toFixed(2) + '</td></tr>';\n  });\n\n  var foot = '<tr><td colspan=\"7\" class=\"r\">Subtotal</td><td class=\"r\">' + t.subtotal.toFixed(2) + '</td></tr>' +\n    '<tr><td colspan=\"7\" class=\"r\">VAT Amount</td><td class=\"r\">' + t.vatAmount.toFixed(2) + '</td></tr>' +\n    '<tr><td colspan=\"7\" class=\"r\" style=\"font-size:14px;\">GRAND TOTAL</td>' +\n    '<td class=\"r\" style=\"color:var(--orange);font-size:14px;\">' + t.grandTotal.toFixed(2) + ' ' + cur + '</td></tr>';\n\n  buildPrintShell({\n    logo: logoDataUrl || LOGO_SRC,\n    title: 'QUOTATION',\n    partyLabel: 'Quote To Customer',\n    companyName: gv('compName'),\n    companyAddress: gv('compAddr'),\n    companyLine2: gv('compWeb'),\n    companyLine3: gv('compCR') ? 'CR #: ' + gv('compCR') : '',\n    partyName: gv('custName'),\n    partyAddress: gv('custAddr'),\n    partyExtra: gv('custMobile') ? 'Mobile: ' + gv('custMobile') : '',\n    meta: [\n      ['Quotation Ref#:', gv('quotNo'), true],\n      ['Quotation Date:', fmtDateDot(document.getElementById('quotDate').value)],\n      ['BL / AWB No.:', gv('blNo')],\n      ['No. of Pcs.:', gv('numPcs')],\n      ['Origin:', gv('shipOrigin')],\n      ['Destination:', gv('shipDest')],\n      ['Gross Weight:', gv('grossWt') ? gv('grossWt') + ' KG' : ''],\n      ['Chargeable Weight:', gv('chargeWt') ? gv('chargeWt') + ' KG' : ''],\n      ['Commodity:', gv('qCommodity')],\n      ['Shipment Mode:', gv('qShipMode')],\n      ['Shipment Terms:', gv('qShipTerms')]\n    ],\n    itemsHead: '<tr><th style=\"width:36px;\">#</th><th>Particulars</th>' +\n      '<th style=\"width:90px;\">HS Code</th><th style=\"width:50px;\">Curr</th>' +\n      '<th style=\"width:60px;\" class=\"r\">Qty</th><th style=\"width:100px;\" class=\"r\">Unit Price</th>' +\n      '<th style=\"width:60px;\" class=\"r\">VAT%</th><th style=\"width:120px;\" class=\"r\">Total Amount</th></tr>',\n    itemsBody: body,\n    itemsFoot: foot,\n    words: quoteNumberToWords(t.grandTotal) + ' ' + (QUOTE_CURR_NAMES[cur] || cur) + ' Only',\n    terms: gv('termsConditions'),\n    bankSource: 'auto'\n  });\n}\n\nfunction fmtDateDot(v) {\n  if (!v) return '';\n  return new Date(v).toLocaleDateString('en-GB', { day:'2-digit', month:'2-digit', year:'numeric' }).replace(/\\//g, '.');\n}\n\nfunction quoteNumberToWords(num) {\n  var whole = Math.floor(num);\n  var decimal = Math.round((num - whole) * 100);\n  var result = quoteConvertWhole(whole);\n  if (decimal > 0) result += ' and ' + quoteConvertWhole(decimal) + ' Fils';\n  return result;\n}\nfunction quoteConvertWhole(n) {\n  if (n === 0) return 'Zero';\n  if (n < 20) return QUOTE_NUM_WORDS[n];\n  if (n < 100) { var t = Math.floor(n / 10) * 10, o = n % 10; return QUOTE_NUM_WORDS[t] + (o > 0 ? ' ' + QUOTE_NUM_WORDS[o] : ''); }\n  if (n < 1000) { var hh = Math.floor(n / 100), rr = n % 100; return QUOTE_NUM_WORDS[hh] + ' Hundred' + (rr > 0 ? ' and ' + quoteConvertWhole(rr) : ''); }\n  if (n < 1000000) { var tt = Math.floor(n / 1000), r2 = n % 1000; return quoteConvertWhole(tt) + ' Thousand' + (r2 > 0 ? ' ' + quoteConvertWhole(r2) : ''); }\n  var m = Math.floor(n / 1000000), r3 = n % 1000000;\n  return quoteConvertWhole(m) + ' Million' + (r3 > 0 ? ' ' + quoteConvertWhole(r3) : '');\n}\n\nfunction saveQuoteSheet() {\n  var t = quoteComputeTotals();\n  var cur = document.getElementById('invCurrency').value;\n  var payload = {\n    quotationNo: document.getElementById('quotNo').value.trim(),\n    quotationDate: document.getElementById('quotDate').value,\n    companyName: document.getElementById('compName').value.trim(),\n    companyAddress: document.getElementById('compAddr').value.trim(),\n    website: document.getElementById('compWeb').value.trim(),\n    crNumber: document.getElementById('compCR').value.trim(),\n    quoteTo: document.getElementById('custName').value.trim(),\n    customerAddress: document.getElementById('custAddr').value.trim(),\n    customerMobile: document.getElementById('custMobile').value.trim(),\n    blNo: document.getElementById('blNo').value.trim(),\n    numPcs: document.getElementById('numPcs').value.trim(),\n    origin: document.getElementById('shipOrigin').value.trim(),\n    destination: document.getElementById('shipDest').value.trim(),\n    grossWeight: document.getElementById('grossWt').value.trim(),\n    chargeableWeight: document.getElementById('chargeWt').value.trim(),\n    commodity: document.getElementById('qCommodity').value.trim(),\n    currency: cur,\n    vatRate: document.getElementById('vatRate').value.trim(),\n    subtotal: t.subtotal, vatAmount: t.vatAmount, grandTotal: t.grandTotal,\n    amountWords: quoteNumberToWords(t.grandTotal) + ' ' + (QUOTE_CURR_NAMES[cur] || cur) + ' Only',\n    terms: document.getElementById('termsConditions').value.trim(),\n    shipMode: document.getElementById('qShipMode').value,\n    shipTerms: document.getElementById('qShipTerms').value,\n    items: lineItems\n  };\n  toast('Saving quotation to Cloud…');\n  run('saveQuotation', function(res) { toast('✔ Quotation saved — ' + res.quotationNo); }, payload);\n}\n\nfunction resetQuote() {\n  if (!confirm('Reset quotation data?')) return;\n  document.getElementById('custName').value = '';\n  document.getElementById('custAddr').value = '';\n  document.getElementById('custMobile').value = '';\n  genQuoteRef();\n  document.getElementById('quotDate').value = new Date().toISOString().split('T')[0];\n  ['blNo','numPcs','shipOrigin','shipDest','grossWt','chargeWt','qCommodity','termsConditions','qShipMode','qShipTerms'].forEach(function(id){ document.getElementById(id).value = ''; });\n  document.getElementById('vatRate').value = 0;\n  document.getElementById('invCurrency').value = 'BHD';\n  qRemoveLogo();\n  lineItems = [{ desc:'', hsCode:'', qty:1, price:0, vat:0 }];\n  renderQuoteItems();\n}\n\n/* =====================================================\n   DELIVERY NOTE — editor logic (print output = invoice layout)\n===================================================== */\nvar dnItems = [{ desc:'', hsCode:'', qty:1, unit:'Pcs', remarks:'' }];\nvar DN_UNITS = ['Pcs','Pallet','Boxes','Cartons','Bags','Drums','Rolls','Sets','Units','Crates','Bundles'];\n\nfunction genDNRef() {\n  var now = new Date();\n  var ymd = now.getFullYear() + ('0' + (now.getMonth() + 1)).slice(-2) + ('0' + now.getDate()).slice(-2);\n  var rand = Math.floor(1000 + Math.random() * 9000);\n  document.getElementById('dDnNo').value = 'WRL-DN-BH-' + ymd + '-' + rand;\n}\n\nfunction renderDNItems() {\n  var c = document.getElementById('dItemsEditor');\n  var h = '';\n  dnItems.forEach(function(item, idx) {\n    var sel = '<select onchange=\"dnUpdateItem(' + idx + ',\\'unit\\',this.value)\">';\n    DN_UNITS.forEach(function(u) { sel += '<option value=\"' + u + '\"' + (item.unit === u ? ' selected' : '') + '>' + u + '</option>'; });\n    sel += '</select>';\n    h += '<div class=\"line-item-row dn\">' +\n      '<input type=\"text\" placeholder=\"Description\" value=\"' + esc(item.desc) + '\" onchange=\"dnUpdateItem(' + idx + ',\\'desc\\',this.value)\">' +\n      '<input type=\"text\" placeholder=\"HS Code\" value=\"' + esc(item.hsCode) + '\" onchange=\"dnUpdateItem(' + idx + ',\\'hsCode\\',this.value)\">' +\n      '<input type=\"number\" placeholder=\"Qty\" value=\"' + item.qty + '\" min=\"1\" onchange=\"dnUpdateItem(' + idx + ',\\'qty\\',this.value)\">' +\n      sel +\n      '<input type=\"text\" placeholder=\"Remarks\" value=\"' + esc(item.remarks) + '\" onchange=\"dnUpdateItem(' + idx + ',\\'remarks\\',this.value)\">' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--line); padding:5px 10px; font-size:11px;\" onclick=\"dnRemoveItem(' + idx + ')\">&#10060;</button>' +\n      '</div>';\n  });\n  c.innerHTML = h;\n}\nfunction dnUpdateItem(idx, field, value) {\n  if (field === 'qty') dnItems[idx][field] = parseFloat(value) || 0;\n  else dnItems[idx][field] = value;\n}\nfunction dnAddItem() { dnItems.push({ desc:'', hsCode:'', qty:1, unit:'Pcs', remarks:'' }); renderDNItems(); }\nfunction dnRemoveItem(idx) { dnItems.splice(idx, 1); renderDNItems(); }\n\n/* ---------- DELIVERY NOTE print — same layout as TAX INVOICE ---------- */\nfunction buildDNPrint() {\n  var body = '';\n  dnItems.forEach(function(it, i) {\n    body += '<tr><td>' + (i + 1) + '</td>' +\n      '<td>' + esc(it.desc) + '</td>' +\n      '<td>' + esc(it.hsCode) + '</td>' +\n      '<td class=\"r\">' + it.qty + '</td>' +\n      '<td>' + esc(it.unit) + '</td>' +\n      '<td>' + esc(it.remarks) + '</td></tr>';\n  });\n\n  buildPrintShell({\n    logo: LOGO_SRC,\n    title: 'DELIVERY NOTE',\n    partyLabel: 'Deliver To',\n    companyName: gv('dCompName'),\n    companyAddress: gv('dCompAddr'),\n    companyLine2: gv('dCompWeb'),\n    companyLine3: gv('dCR') ? 'CR #: ' + gv('dCR') : '',\n    partyName: gv('dCustName'),\n    partyAddress: gv('dCustAddr'),\n    partyExtra: gv('dCustMobile') ? 'Mobile: ' + gv('dCustMobile') : '',\n    meta: [\n      ['Delivery Note Ref#:', gv('dDnNo'), true],\n      ['Delivery Date:', fmtDateDot(document.getElementById('dDnDate').value)],\n      ['BL / AWB No.:', gv('dBlNo')],\n      ['No. of Pcs.:', gv('dNumPcs')],\n      ['Origin:', gv('dOrigin')],\n      ['Destination:', gv('dDest')],\n      ['Gross Weight:', gv('dGrossWt') ? gv('dGrossWt') + ' KG' : ''],\n      ['Chargeable Weight:', gv('dChargeWt') ? gv('dChargeWt') + ' KG' : ''],\n      ['Commodity:', gv('dCommodity')],\n      ['Delivered By:', gv('dDeliveredBy')],\n      ['Truck No:', gv('dTruckNo')],\n      ['Driver Name:', gv('dDriverName')]\n    ],\n    itemsHead: '<tr><th style=\"width:36px;\">#</th><th>Particulars</th>' +\n      '<th style=\"width:110px;\">HS Code</th><th style=\"width:70px;\" class=\"r\">Qty</th>' +\n      '<th style=\"width:80px;\">Unit</th><th style=\"width:130px;\">Remarks</th></tr>',\n    itemsBody: body,\n    itemsFoot: '',\n    words: '',\n    terms: gv('dTerms'),\n    bankSource: 'auto'\n  });\n}\n\nfunction saveDNSheet() {\n  var payload = {\n    deliveryNo: document.getElementById('dDnNo').value.trim(),\n    deliveryDate: document.getElementById('dDnDate').value,\n    companyName: document.getElementById('dCompName').value.trim(),\n    companyAddress: document.getElementById('dCompAddr').value.trim(),\n    website: document.getElementById('dCompWeb').value.trim(),\n    crNumber: document.getElementById('dCR').value.trim(),\n    deliverTo: document.getElementById('dCustName').value.trim(),\n    customerAddress: document.getElementById('dCustAddr').value.trim(),\n    customerMobile: document.getElementById('dCustMobile').value.trim(),\n    blNo: document.getElementById('dBlNo').value.trim(),\n    numPcs: document.getElementById('dNumPcs').value.trim(),\n    origin: document.getElementById('dOrigin').value.trim(),\n    destination: document.getElementById('dDest').value.trim(),\n    grossWeight: document.getElementById('dGrossWt').value.trim(),\n    chargeableWeight: document.getElementById('dChargeWt').value.trim(),\n    commodity: document.getElementById('dCommodity').value.trim(),\n    deliveredBy: document.getElementById('dDeliveredBy').value.trim(),\n    truckNo: document.getElementById('dTruckNo').value.trim(),\n    driverName: document.getElementById('dDriverName').value.trim(),\n    terms: document.getElementById('dTerms').value.trim(),\n    items: dnItems\n  };\n  toast('Saving delivery note to Cloud…');\n  run('saveDeliveryNote', function(res) { toast('✔ Delivery Note saved — ' + res.deliveryNo); }, payload);\n}\n\nfunction resetDN() {\n  if (!confirm('Reset delivery note data?')) return;\n  document.getElementById('dCustName').value = '';\n  document.getElementById('dCustAddr').value = '';\n  document.getElementById('dCustMobile').value = '';\n  genDNRef();\n  document.getElementById('dDnDate').value = new Date().toISOString().split('T')[0];\n  ['dBlNo','dNumPcs','dOrigin','dDest','dGrossWt','dChargeWt','dCommodity','dDeliveredBy','dTruckNo','dDriverName','dTerms'].forEach(function(id){ document.getElementById(id).value = ''; });\n  dnItems = [{ desc:'', hsCode:'', qty:1, unit:'Pcs', remarks:'' }];\n  renderDNItems();\n}\n\n/* ---------- init quote & delivery note editors (invoice init lives in window.onload) ---------- */\n(function(){\n  genQuoteRef();\n  document.getElementById('quotDate').value = new Date().toISOString().split('T')[0];\n  renderQuoteItems();\n  quoteRefreshTotals();\n  genDNRef();\n  document.getElementById('dDnDate').value = new Date().toISOString().split('T')[0];\n  renderDNItems();\n})();\n\n/* =====================================================\n   UTILITIES\n===================================================== */\nfunction gv(id){ return document.getElementById(id).value.trim(); }\nfunction setv(id, v){ document.getElementById(id).value = (v === undefined || v === null) ? '' : v; }\nfunction setTxt(id, v){ document.getElementById(id).textContent = v || ''; }\nfunction round2(n){ return Math.round(n * 100) / 100; }\n/* ---------- MULTI-CURRENCY SUPPORT ---------- */\nvar CURR = {\n  'INR': { sym:'₹',   major:'Rupees',           minor:'Paise',   indian:true  },\n  'BHD': { sym:'BHD', major:'Bahraini Dinars',  minor:'Fils',    indian:false },\n  'USD': { sym:'$',   major:'US Dollars',       minor:'Cents',   indian:false },\n  'EUR': { sym:'€',   major:'Euros',            minor:'Cents',   indian:false },\n  'GBP': { sym:'£',   major:'Pounds Sterling',  minor:'Pence',   indian:false },\n  'AED': { sym:'AED', major:'UAE Dirhams',      minor:'Fils',    indian:false },\n  'SAR': { sym:'SAR', major:'Saudi Riyals',     minor:'Halalas', indian:false },\n  'QAR': { sym:'QAR', major:'Qatari Riyals',    minor:'Dirhams', indian:false },\n  'KWD': { sym:'KWD', major:'Kuwaiti Dinars',   minor:'Fils',    indian:false },\n  'OMR': { sym:'OMR', major:'Omani Rials',      minor:'Baisa',   indian:false },\n  'JPY': { sym:'¥',   major:'Japanese Yen',     minor:'',        indian:false },\n  'CNY': { sym:'¥',   major:'Chinese Yuan',     minor:'Fen',     indian:false }\n};\nfunction fmt(n, cur){\n  var info = CURR[cur] || { sym: cur };\n  return info.sym + ' ' + round2(n).toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});\n}\nfunction esc(s){ return String(s).replace(/[&<>\"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]; }); }\n\n/* Company name printed in logo colours: main words purple, last word orange */\nfunction coloredNameHtml(name){\n  var parts = String(name || '').trim().split(/\\s+/).filter(Boolean);\n  if (!parts.length) return '';\n  if (parts.length === 1) return '<span style=\"color:var(--purple);\">' + esc(parts[0].toUpperCase()) + '</span>';\n  var last = parts.pop();\n  return '<span style=\"color:var(--purple);\">' + esc(parts.join(' ').toUpperCase()) + '</span> ' +\n         '<span style=\"color:var(--orange);\">' + esc(last) + '</span>';\n}\n\nvar ONES=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];\nvar TENS=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];\nfunction twoDigits(n){ return n<20 ? ONES[n] : TENS[Math.floor(n/10)] + (n%10 ? ' ' + ONES[n%10] : ''); }\nfunction threeDigits(n){\n  var h=Math.floor(n/100), r=n%100, s='';\n  if(h) s = ONES[h] + ' Hundred' + (r ? ' ' : '');\n  if(r) s += twoDigits(r);\n  return s;\n}\nfunction indianWords(num){\n  var parts = [];\n  var crore = Math.floor(num / 10000000); num %= 10000000;\n  var lakh  = Math.floor(num / 100000);   num %= 100000;\n  var thou  = Math.floor(num / 1000);     num %= 1000;\n  if(crore) parts.push(threeDigits(crore) + ' Crore');\n  if(lakh)  parts.push(threeDigits(lakh) + ' Lakh');\n  if(thou)  parts.push(threeDigits(thou) + ' Thousand');\n  if(num)   parts.push(threeDigits(num));\n  return parts.join(' ');\n}\nfunction westernWords(num){\n  var parts = [];\n  var scales = [[1000000000,'Billion'],[1000000,'Million'],[1000,'Thousand']];\n  for (var i = 0; i < scales.length; i++) {\n    var v = Math.floor(num / scales[i][0]);\n    if (v) { parts.push(threeDigits(v) + ' ' + scales[i][1]); num %= scales[i][0]; }\n  }\n  if (num) parts.push(threeDigits(num));\n  return parts.join(' ');\n}\nfunction numberToWords(num, cur){\n  var info = CURR[cur] || CURR['INR'];\n  var whole = Math.floor(num);\n  var frac  = Math.round((num - whole) * 100);\n  if (!whole && !frac) return '';\n  var s = whole ? info.major + ' ' + (info.indian ? indianWords(whole) : westernWords(whole)) : '';\n  if (frac && info.minor) s += (s ? ' and ' : '') + twoDigits(frac) + ' ' + info.minor;\n  return s;\n}\n</script>\n<script>\n/* ACCOUNTING tab — loaded after the original script, reuses its helpers (esc, gv, toast, CURR) and CSS classes. */\n(function () {\n  var root = document.getElementById('viewAcc');\n  var A = { accounts: [], journal: [], invoices: [] };\n  var tab = 'overview', cur = '', curPicked = false, from = '', to = '', led = '', lastReceipt = null, lastJob = null;\n  var TABS = ['overview', 'vouchers', 'jobs', 'journal', 'ledger', 'reports', 'accounts'];\n  var TL = { overview: 'Overview', vouchers: 'Income / Expense', jobs: 'Job Profit', journal: 'Journal', ledger: 'Ledger', reports: 'Reports', accounts: 'Chart of Accounts' };\n  var DEBIT = { asset: 1, expense: 1 };\n\n  function call(fn, arg, ok, onFail) {\n    function fail(msg) { toast('⚠ ' + msg, true); if (onFail) onFail(msg); }\n    try {\n      var r = google.script.run.withFailureHandler(function (e) { fail((e && e.message) || String(e)); }).withSuccessHandler(ok);\n      if (typeof r[fn] !== 'function') { fail('Server function \"' + fn + '\" was not found'); return; }   // e.g. an older Code.gs is deployed\n      r[fn](arg);\n    } catch (e) { fail(e.message || String(e)); }\n  }\n  function showError(msg) {\n    var hint = /not found|not a function|unknown function/i.test(msg)\n      ? 'The Code.gs running on the server is older than this page (it has no accounting functions). In Apps Script paste the latest <b>Code.gs</b>, then <b>Deploy → Manage deployments → ✏ Edit → Version: New version → Deploy</b>, and reload this page.'\n      : /authori|permission|access/i.test(msg)\n        ? 'Google needs permission to use the sheet. In the Apps Script editor run any function once (Run ▶), accept the permissions, then deploy a New version.'\n        : /lock/i.test(msg) ? 'Another save was still running. Wait a few seconds and press Retry.'\n        : 'Press Retry. If it keeps failing, open Apps Script → Executions to see the full error.';\n    root.innerHTML = '<div class=\"wrap\" style=\"grid-template-columns:1fr;max-width:1100px;\"><div class=\"card\"><h3>Accounting could not load</h3>' +\n      '<p style=\"margin:12px 0;font-weight:700;color:#c0392b;\">' + esc(msg) + '</p><p style=\"margin-bottom:14px;line-height:1.5;\">' + hint + '</p>' +\n      '<div class=\"btn-bar\" style=\"margin:0;\"><button class=\"btn btn-orange\" onclick=\"ACC.retry()\">↻ Retry</button></div></div></div>';\n  }\n  function today() { return new Date().toISOString().slice(0, 10); }\n  function n2(v) { v = Math.round(v * 100) / 100; if (!v) v = 0; return v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }\n  function acct(c) { return A.accounts.filter(function (a) { return a.code === c; })[0]; }\n  function nm(c) { var a = acct(c); return a ? c + ' · ' + a.name : c; }\n  function net(a, x) { return DEBIT[a.type] ? x.dr - x.cr : x.cr - x.dr; }\n  function currencies() {\n    var s = {}; A.journal.forEach(function (e) { s[e.currency] = (s[e.currency] || 0) + 1; });\n    return Object.keys(s).sort(function (a, b) { return s[b] - s[a]; });\n  }\n  /* balances per account for the selected currency (and optional date range) */\n  function bal(o) {\n    var m = {};\n    A.journal.forEach(function (e) {\n      if (e.currency !== cur || (o.from && e.date < o.from) || (o.to && e.date > o.to)) return;\n      e.lines.forEach(function (l) { var b = m[l.acc] || (m[l.acc] = { dr: 0, cr: 0 }); b.dr += l.dr; b.cr += l.cr; });\n    });\n    return m;\n  }\n  function load() {\n    call('accGetAll', null, function (r) { A = r; if (!curPicked || !cur) cur = currencies()[0] || cur || 'BHD'; render(); }, showError);\n  }\n  function row(l, v1, v2) { return '<tr><td>' + esc(l) + '</td><td class=\"num\">' + (v1 || '') + '</td>' + (v2 !== undefined ? '<td class=\"num\">' + v2 + '</td>' : '') + '</tr>'; }\n  function tot(l, v1, v2) { return row(l, v1, v2).replace('<tr>', '<tr class=\"tot\">'); }\n  function sec(title, head, rows) {\n    return '<div class=\"rpt-sec\"><h3>' + title + '</h3><div class=\"acc-scroll\"><table class=\"rpt\"><thead><tr>' + head +\n      '</tr></thead><tbody>' + rows + '</tbody></table></div></div>';\n  }\n  function modal(html) {\n    document.getElementById('accModalBody').innerHTML = html;\n    document.getElementById('accModal').classList.add('open');\n  }\n  function closeModal() { document.getElementById('accModal').classList.remove('open'); }\n  var CANCEL = '<button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"ACC.close()\">Cancel</button>';\n\n  /* ---------- views ---------- */\n  function vOverview() {\n    var b = bal({}), inc = 0, exp = 0, ar = 0, cash = 0;\n    A.accounts.forEach(function (a) {\n      var x = b[a.code]; if (!x) return; var v = net(a, x);\n      if (a.type === 'income') inc += v; else if (a.type === 'expense') exp += v;\n      if (a.code === '1200') ar += v; if (a.code === '1000' || a.code === '1100') cash += v;\n    });\n    var k = [['Revenue', inc], ['Expenses', exp], ['Net profit', inc - exp], ['Receivables', ar], ['Cash & bank', cash]]\n      .map(function (x) { return '<div class=\"kpi\"><span>' + x[0] + ' (' + esc(cur) + ')</span><b>' + n2(x[1]) + '</b></div>'; }).join('');\n    var rows = A.invoices.map(function (i, ix) {\n      return '<tr><td><b>' + esc(i.invoiceNo) + '</b></td><td>' + esc(i.invoiceDate) + '</td><td>' + esc(i.billTo) + '</td>' +\n        '<td class=\"num\">' + n2(i.grandTotal) + ' ' + esc(i.currency) + '</td><td class=\"num\">' + n2(i.paid) + '</td>' +\n        '<td class=\"num\">' + n2(i.balance) + '</td>' +\n        '<td class=\"num\">' + (i.hasJob ? n2(i.jobCost) : '—') + '</td><td class=\"num\">' + (i.hasJob ? '<b class=\"' + (i.profit < 0 ? 'neg' : 'pos') + '\">' + n2(i.profit) + '</b>' : '<span title=\"No job yet — create one in the JOB tab\" style=\"color:var(--muted);\">—</span>') + '</td>' +\n        '<td><span class=\"st st-' + i.status + '\">' + i.status + '</span></td>' +\n        '<td>' + (i.balance > 0.004 ? '<button class=\"btn btn-orange\" style=\"padding:5px 10px;\" onclick=\"ACC.pay(' + ix + ')\">Receive</button>' : '') + '</td></tr>';\n    }).join('') || '<tr><td colspan=\"10\" style=\"text-align:center;color:var(--muted);padding:18px;\">No invoices yet. Save a TAX INVOICE and it posts here automatically.</td></tr>';\n    return '<div class=\"kpis\">' + k + '</div>' + quickButtons() + '<h3 style=\"margin-top:16px;\">Receivables</h3><div class=\"acc-scroll\"><table class=\"items\"><thead><tr>' +\n      '<th>Invoice</th><th>Date</th><th>Customer</th><th>Total</th><th>Paid</th><th>Balance</th><th>Job Cost</th><th>Profit</th><th>Status</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>' + vReceipts();\n  }\n  function quickButtons() {\n    return '<div class=\"btn-bar\" style=\"margin:14px 0 0;\"><button class=\"btn btn-orange\" onclick=\"ACC.voucher(\\'expense\\')\">＋ Expense</button>' +\n      '<button class=\"btn\" style=\"background:#1e7a3c;color:#fff;\" onclick=\"ACC.voucher(\\'income\\')\">＋ Income</button></div>';\n  }\n  /* ---- receipts list (every payment received has an A4 receipt) ---- */\n  function vReceipts() {\n    var by = {}; A.invoices.forEach(function (i) { by[i.id] = i; });\n    var list = A.journal.filter(function (e) { return e.source === 'payment' && e.extra && e.extra.receiptNo; })\n      .sort(function (a, b) { return a.date < b.date ? 1 : (a.date > b.date ? -1 : (a.extra.receiptNo < b.extra.receiptNo ? 1 : -1)); }).slice(0, 100);\n    var rows = list.map(function (e) {\n      var i = by[e.ref] || {};\n      return '<tr><td><b>' + esc(e.extra.receiptNo) + '</b></td><td style=\"white-space:nowrap\">' + esc(e.date) + '</td><td>' + esc(i.billTo || '') + '</td><td>' + esc(i.invoiceNo || e.ref) +\n        '</td><td>' + esc(e.extra.method || '') + '</td><td class=\"num\">' + n2(e.lines[1] ? e.lines[1].cr : 0) + ' ' + esc(e.currency) + '</td>' +\n        '<td><button class=\"btn btn-white\" style=\"border:1px solid var(--purple);padding:4px 10px;\" onclick=\"ACC.rcpt(\\'' + e.id + '\\')\">🖨 Receipt</button></td></tr>';\n    }).join('') || '<tr><td colspan=\"7\" style=\"text-align:center;color:var(--muted);padding:18px;\">No receipts yet. Press <b>Receive</b> on an invoice above and a receipt is created.</td></tr>';\n    return '<h3 style=\"margin-top:18px;\">Receipts</h3><div class=\"acc-scroll\"><table class=\"items\"><thead><tr><th>Receipt No</th><th>Date</th><th>Customer</th><th>Invoice</th><th>Mode</th><th>Amount</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';\n  }\n  /* ---- simple Income / Expense vouchers ---- */\n  function voucherAmt(e) { var l = e.lines[0] || {}; return Math.max(l.dr || 0, l.cr || 0); }\n  function vVouchers() {\n    var inc = 0, exp = 0;\n    var list = A.journal.filter(function (e) { return e.source === 'voucher'; }).sort(function (a, b) { return a.date < b.date ? 1 : (a.date > b.date ? -1 : 0); });\n    list.forEach(function (e) { if (e.currency !== cur) return; if ((e.extra || {}).kind === 'income') inc += voucherAmt(e); else exp += voucherAmt(e); });\n    var rows = list.map(function (e) {\n      var x = e.extra || {}, isInc = x.kind === 'income', a = acct(x.category);\n      return '<tr><td><b>' + esc(x.voucherNo || '') + '</b></td><td style=\"white-space:nowrap\">' + esc(e.date) + '</td>' +\n        '<td><span class=\"st st-' + (isInc ? 'Paid' : 'Unpaid') + '\">' + (isInc ? 'Income' : 'Expense') + '</span></td><td>' + esc(a ? a.name : (x.category || '')) + '</td>' +\n        '<td>' + esc([x.party, x.description].filter(Boolean).join(' — ')) + (x.ref ? ' <span style=\"color:var(--muted)\">#' + esc(x.ref) + '</span>' : '') + '</td>' +\n        '<td>' + esc(x.method || '') + '</td><td class=\"num\">' + n2(voucherAmt(e)) + ' ' + esc(e.currency) + '</td>' +\n        '<td style=\"white-space:nowrap\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);padding:4px 10px;\" title=\"Edit\" onclick=\"ACC.voucher(\\'' + (isInc ? 'income' : 'expense') + '\\',\\'' + e.id + '\\')\">✎</button> ' +\n        '<button class=\"row-del\" title=\"Delete\" onclick=\"ACC.del(\\'' + e.id + '\\')\">✕</button></td></tr>';\n    }).join('') || '<tr><td colspan=\"8\" style=\"text-align:center;color:var(--muted);padding:18px;\">No income or expense entries yet. Use the buttons above: one simple entry, the debit and credit are posted for you.</td></tr>';\n    var kp = [['Other income', inc], ['Expenses', exp], ['Net', inc - exp]].map(function (x) { return '<div class=\"kpi\"><span>' + x[0] + ' (' + esc(cur) + ')</span><b>' + n2(x[1]) + '</b></div>'; }).join('');\n    return quickButtons() + '<div class=\"kpis\" style=\"grid-template-columns:repeat(3,1fr);margin-top:12px;\">' + kp + '</div>' +\n      '<div class=\"acc-scroll\" style=\"margin-top:12px;\"><table class=\"items\"><thead><tr><th>No</th><th>Date</th><th>Type</th><th>Category</th><th>Paid to / Received from</th><th>Mode</th><th>Amount</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';\n  }\n  /* ---- job profit (cost sheets made in the JOB tab) ---- */\n  function vJobs() {\n    var list = A.jobs || [], s = 0, c = 0;\n    list.forEach(function (j) { if (j.currency === cur) { s += j.selling; c += j.cost; } });\n    var kp = [['Job selling', s], ['Agent cost', c], ['Job profit', s - c]].map(function (x) { return '<div class=\"kpi\"><span>' + x[0] + ' (' + esc(cur) + ')</span><b>' + n2(x[1]) + '</b></div>'; }).join('') +\n      '<div class=\"kpi\"><span>Margin (' + esc(cur) + ')</span><b>' + (s ? (Math.round((s - c) / s * 1000) / 10).toFixed(1) : '0.0') + ' %</b></div>';\n    var rows = list.map(function (j, ix) {\n      var mism = j.invSub !== null && j.invSub !== undefined && Math.abs(j.invSub - j.selling) > 0.01;\n      return '<tr><td><b>' + esc(j.jobNo) + '</b></td><td style=\"white-space:nowrap\">' + esc(j.jobDate) + '</td><td>' + esc(j.customer) + '</td><td>' + esc(j.invoiceNo || '—') + '</td>' +\n        '<td class=\"num\">' + n2(j.selling) + ' ' + esc(j.currency) + (mism ? ' <span title=\"Differs from the invoice amount before tax: ' + n2(j.invSub) + '\" style=\"cursor:help;\">⚠</span>' : '') + '</td>' +\n        '<td class=\"num\">' + n2(j.cost) + '</td><td class=\"num\"><b class=\"' + (j.profit < 0 ? 'neg' : 'pos') + '\">' + n2(j.profit) + '</b></td><td class=\"num\">' + j.margin.toFixed(1) + '%</td>' +\n        '<td><span class=\"st st-' + (j.status === '—' ? 'job' : j.status) + '\">' + (j.status === '—' ? 'No cost' : j.status) + '</span>' + (j.outstanding > 0.004 ? ' <span style=\"color:var(--muted);font-size:11px;\">due ' + n2(j.outstanding) + '</span>' : '') + '</td>' +\n        '<td style=\"white-space:nowrap\"><button class=\"btn btn-white\" style=\"border:1px solid var(--purple);padding:4px 10px;\" onclick=\"ACC.jobPdf(' + ix + ')\">📄 PDF</button> ' +\n        (j.outstanding > 0.004 ? '<button class=\"btn btn-orange\" style=\"padding:4px 10px;\" onclick=\"ACC.payAgent(' + ix + ')\">Pay agent</button>' : '') + '</td></tr>';\n    }).join('') || '<tr><td colspan=\"10\" style=\"text-align:center;color:var(--muted);padding:18px;\">No jobs yet. Open the <b>JOB</b> tab, pull an invoice, add the agent and cost on each line, and save.</td></tr>';\n    return '<div class=\"kpis\" style=\"grid-template-columns:repeat(4,1fr);\">' + kp + '</div>' +\n      '<p class=\"autosave-note\" style=\"margin:10px 0 0;\">The cost of every job is posted to the accounts automatically (Direct Shipment Costs / Accounts Payable) — do not enter the same agent cost again as an expense.</p>' +\n      '<div class=\"acc-scroll\" style=\"margin-top:10px;\"><table class=\"items\"><thead><tr><th>Job</th><th>Date</th><th>Customer</th><th>Invoice</th><th>Selling</th><th>Cost</th><th>Profit</th><th>Margin</th><th>Agent payable</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';\n  }\n  function vJournal() {\n    var rows = A.journal.slice().sort(function (a, b) { return a.date < b.date ? 1 : (a.date > b.date ? -1 : 0); }).map(function (e) {\n      var ls = e.lines.map(function (l) {\n        return '<div class=\"jl\"><span>' + esc(nm(l.acc)) + '</span><span class=\"num\">' + (l.dr ? n2(l.dr) : '') + '</span><span class=\"num\">' + (l.cr ? n2(l.cr) : '') + '</span></div>';\n      }).join('');\n      return '<tr><td style=\"white-space:nowrap\">' + esc(e.date) + '</td><td><b>' + esc(e.memo || '—') + '</b> <span class=\"st st-' + e.source + '\">' + e.source + '</span>' + ls +\n        '</td><td>' + esc(e.currency) + '</td><td style=\"white-space:nowrap\">' + (e.source === 'payment' && e.extra && e.extra.receiptNo ? '<button class=\"btn btn-white\" style=\"border:1px solid var(--purple);padding:3px 8px;\" title=\"Receipt\" onclick=\"ACC.rcpt(\\'' + e.id + '\\')\">🧾</button> ' : '') + ((e.source === 'invoice' || e.source === 'job') ? '' : '<button class=\"row-del\" title=\"Delete entry\" onclick=\"ACC.del(\\'' + e.id + '\\')\">✕</button>') + '</td></tr>';\n    }).join('') || '<tr><td colspan=\"4\" style=\"text-align:center;color:var(--muted);padding:18px;\">No entries yet.</td></tr>';\n    return '<div class=\"btn-bar\" style=\"margin:0 0 10px;\"><button class=\"btn btn-orange\" onclick=\"ACC.newEntry()\">＋ New Journal Entry</button></div>' +\n      '<div class=\"acc-scroll\"><table class=\"items\"><thead><tr><th>Date</th><th>Entry (account, debit, credit)</th><th>Cur</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';\n  }\n  function vLedger() {\n    var sel = led || (A.accounts[0] || {}).code, a = acct(sel), run = 0, rows = '';\n    A.journal.slice().sort(function (x, y) { return x.date < y.date ? -1 : (x.date > y.date ? 1 : 0); }).forEach(function (e) {\n      if (e.currency !== cur || (from && e.date < from) || (to && e.date > to)) return;\n      e.lines.forEach(function (l) {\n        if (l.acc !== sel || !a) return;\n        run += DEBIT[a.type] ? l.dr - l.cr : l.cr - l.dr;\n        rows += '<tr><td style=\"white-space:nowrap\">' + esc(e.date) + '</td><td>' + esc(e.memo) + '</td><td class=\"num\">' + (l.dr ? n2(l.dr) : '') +\n          '</td><td class=\"num\">' + (l.cr ? n2(l.cr) : '') + '</td><td class=\"num\"><b>' + n2(run) + '</b></td></tr>';\n      });\n    });\n    var opts = A.accounts.map(function (x) { return '<option value=\"' + x.code + '\"' + (x.code === sel ? ' selected' : '') + '>' + esc(x.code + ' · ' + x.name) + '</option>'; }).join('');\n    return '<div class=\"fld\" style=\"max-width:360px;margin-bottom:10px;\"><label>Account</label><select onchange=\"ACC.setLed(this.value)\">' + opts + '</select></div>' +\n      '<div class=\"acc-scroll\"><table class=\"items\"><thead><tr><th>Date</th><th>Memo</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>' +\n      (rows || '<tr><td colspan=\"5\" style=\"text-align:center;color:var(--muted);padding:18px;\">No movements in ' + esc(cur) + ' for this account.</td></tr>') + '</tbody></table></div>';\n  }\n  function vReports() {\n    var b = bal({ from: from, to: to }), B = bal({ to: to });\n    var tb = '', dT = 0, cT = 0, inc = '', exp = '', iT = 0, eT = 0;\n    A.accounts.forEach(function (a) {\n      var x = b[a.code]; if (!x) return;\n      var d = x.dr - x.cr, dd = d > 0 ? d : 0, cc = d < 0 ? -d : 0; dT += dd; cT += cc;\n      tb += row(a.code + ' · ' + a.name, dd ? n2(dd) : '', cc ? n2(cc) : '');\n      var v = net(a, x);\n      if (a.type === 'income') { inc += row(a.name, n2(v)); iT += v; }\n      if (a.type === 'expense') { exp += row(a.name, n2(v)); eT += v; }\n    });\n    var as = '', li = '', eq = '', aT = 0, lT = 0, qT = 0, ci = 0, ce = 0;\n    A.accounts.forEach(function (a) {\n      var x = B[a.code]; if (!x) return; var v = net(a, x);\n      if (a.type === 'asset') { as += row(a.name, n2(v)); aT += v; }\n      else if (a.type === 'liability') { li += row(a.name, n2(v)); lT += v; }\n      else if (a.type === 'equity') { eq += row(a.name, n2(v)); qT += v; }\n      else if (a.type === 'income') ci += v; else ce += v;\n    });\n    eq += row('Earnings to date', n2(ci - ce)); qT += ci - ce;\n    var sub = function (t) { return '<tr class=\"sub\"><td colspan=\"2\">' + t + '</td></tr>'; };\n    return '<div class=\"btn-bar\" style=\"margin:0;\"><button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"ACC.csv()\">⬇ Export CSV</button> <button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"window.print()\">🖨 Print</button></div>' +\n      sec('Trial Balance', '<th>Account</th><th class=\"num\">Debit</th><th class=\"num\">Credit</th>', tb + tot('Total', n2(dT), n2(cT))) +\n      sec('Profit &amp; Loss', '<th>Account</th><th class=\"num\">' + esc(cur) + '</th>',\n        sub('Income') + inc + tot('Total income', n2(iT)) + sub('Expenses') + exp + tot('Total expenses', n2(eT)) + tot('Net profit', n2(iT - eT))) +\n      sec('Balance Sheet', '<th>Account</th><th class=\"num\">' + esc(cur) + '</th>',\n        sub('Assets') + as + tot('Total assets', n2(aT)) + sub('Liabilities') + li + tot('Total liabilities', n2(lT)) +\n        sub('Equity') + eq + tot('Total equity', n2(qT)) + tot('Liabilities + equity', n2(lT + qT)));\n  }\n  function vAccounts() {\n    var b = bal({});\n    var rows = A.accounts.map(function (a, ix) {\n      var x = b[a.code];\n      return '<tr><td><b>' + esc(a.code) + '</b></td><td>' + esc(a.name) + '</td><td>' + a.type + '</td><td class=\"num\">' + (x ? n2(net(a, x)) : '0.00') +\n        '</td><td><button class=\"btn btn-white\" style=\"border:1px solid var(--line);padding:4px 10px;\" onclick=\"ACC.edit(' + ix + ')\">Edit</button></td></tr>';\n    }).join('');\n    return '<div class=\"grid3\" style=\"margin-bottom:10px;\"><div class=\"fld\"><label>Code</label><input id=\"aCode\" placeholder=\"e.g. 5300\"></div>' +\n      '<div class=\"fld\"><label>Account name</label><input id=\"aName\"></div><div class=\"fld\"><label>Type</label><select id=\"aType\">' +\n      '<option>asset</option><option>liability</option><option>equity</option><option>income</option><option>expense</option></select></div></div>' +\n      '<div class=\"btn-bar\" style=\"margin:0 0 12px;\"><button class=\"btn btn-orange\" onclick=\"ACC.saveAcc()\">💾 Save Account</button></div>' +\n      '<div class=\"acc-scroll\"><table class=\"items\"><thead><tr><th>Code</th><th>Name</th><th>Type</th><th>Balance (' + esc(cur) + ')</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';\n  }\n\n  function render() {\n    var cs = currencies(); if (cs.indexOf(cur) < 0) cs.push(cur);\n    var h = '<div class=\"wrap\" style=\"grid-template-columns:1fr;max-width:1100px;\"><div class=\"card\"><div class=\"acc-bar\">' +\n      TABS.map(function (t) { return '<button class=\"acc-tab' + (t === tab ? ' active' : '') + '\" onclick=\"ACC.go(\\'' + t + '\\')\">' + TL[t] + '</button>'; }).join('') +\n      '<span class=\"acc-sp\"></span><label class=\"acc-cur\">Currency <select onchange=\"ACC.setCur(this.value)\">' +\n      cs.map(function (c) { return '<option' + (c === cur ? ' selected' : '') + '>' + esc(c) + '</option>'; }).join('') + '</select></label></div>';\n    if (tab === 'ledger' || tab === 'reports') {\n      h += '<div class=\"grid2\" style=\"margin-bottom:12px;\"><div class=\"fld\"><label>From</label><input type=\"date\" value=\"' + from + '\" onchange=\"ACC.setRange(\\'from\\',this.value)\"></div>' +\n        '<div class=\"fld\"><label>To' + (tab === 'reports' ? ' / balance sheet date' : '') + '</label><input type=\"date\" value=\"' + to + '\" onchange=\"ACC.setRange(\\'to\\',this.value)\"></div></div>';\n    }\n    h += { overview: vOverview, vouchers: vVouchers, jobs: vJobs, journal: vJournal, ledger: vLedger, reports: vReports, accounts: vAccounts }[tab]() + '</div></div>' +\n      '<div class=\"modal-back no-print\" id=\"accModal\"><div class=\"modal\" id=\"accModalBody\"></div></div>';\n    root.innerHTML = h;\n  }\n\n  /* ---------- actions ---------- */\n  window.ACC = {\n    go: function (t) { tab = t; render(); },\n    setCur: function (v) { cur = v; curPicked = true; render(); },\n    setRange: function (k, v) { if (k === 'from') from = v; else to = v; render(); },\n    setLed: function (v) { led = v; render(); },\n    close: closeModal,\n    retry: function () { load(); },\n    pay: function (ix) {\n      var i = A.invoices[ix]; if (!i) return;\n      modal('<h3>Receive payment — ' + esc(i.invoiceNo) + '</h3><div class=\"grid2\">' +\n        '<div class=\"fld\"><label>Date</label><input id=\"pDate\" type=\"date\" value=\"' + today() + '\"></div>' +\n        '<div class=\"fld\"><label>Amount (' + esc(i.currency) + ')</label><input id=\"pAmt\" type=\"number\" step=\"0.01\" value=\"' + i.balance + '\"></div>' +\n        '<div class=\"fld\"><label>Received in</label><select id=\"pMeth\"><option>Bank</option><option>Cash</option></select></div>' +\n        '<div class=\"fld\"><label>Reference</label><input id=\"pRef\" placeholder=\"Cheque / transfer no\"></div></div>' +\n        '<div class=\"m-actions\">' + CANCEL + '<button class=\"btn btn-orange\" onclick=\"ACC.savePay(' + ix + ')\">💾 Save Receipt</button></div>');\n    },\n    savePay: function (ix) {\n      call('accRecordPayment', { invoiceId: (A.invoices[ix] || {}).id, date: gv('pDate'), amount: gv('pAmt'), method: gv('pMeth'), ref: gv('pRef') },\n        function (r) { A = r; render(); if (r.receipt) { lastReceipt = r.receipt; showReceipt(r.receipt, true); } else toast('✔ Receipt recorded'); });\n    },\n    jobPdf: function (ix) {\n      var j = (A.jobs || [])[ix]; if (!j) return;\n      call('getJob', j.jobNo, function (d) { lastJob = d; showJob(d); });\n    },\n    printJobLast: function () { if (lastJob && window.JOBAPI) window.JOBAPI.print(lastJob); },\n    openJobPanel: function () { if (!lastJob) return; closeModal(); switchDoc('job'); JOB.fillData(lastJob); },\n    payAgent: function (ix) {\n      var j = (A.jobs || [])[ix]; if (!j) return;\n      modal('<h3>Pay agent — ' + esc(j.jobNo) + '</h3><div class=\"grid2\">' +\n        '<div class=\"fld\"><label>Date</label><input id=\"agDate\" type=\"date\" value=\"' + today() + '\"></div>' +\n        '<div class=\"fld\"><label>Amount (' + esc(j.currency) + ') — agent cost still to pay</label><input id=\"agAmt\" type=\"number\" step=\"0.01\" value=\"' + j.outstanding + '\"></div>' +\n        '<div class=\"fld\"><label>Paid from</label><select id=\"agMeth\"><option>Bank</option><option>Cash</option></select></div>' +\n        '<div class=\"fld\"><label>Reference</label><input id=\"agRef\" placeholder=\"Cheque / transfer no\"></div></div>' +\n        '<p class=\"autosave-note\">Agents on this job: ' + esc(j.agents || '—') + '. Posted automatically: <b>Dr</b> Accounts Payable, <b>Cr</b> Cash / Bank.</p>' +\n        '<div class=\"m-actions\">' + CANCEL + '<button class=\"btn btn-orange\" onclick=\"ACC.savePayAgent(' + ix + ')\">💾 Save Payment</button></div>');\n    },\n    savePayAgent: function (ix) {\n      call('accPayAgent', { jobId: (A.jobs[ix] || {}).id, date: gv('agDate'), amount: gv('agAmt'), method: gv('agMeth'), ref: gv('agRef') },\n        function (r) { A = r; render(); toast('✔ Agent payment recorded'); });\n    },\n    rcpt: function (id) { call('accGetReceipt', id, function (r) { lastReceipt = r; showReceipt(r, false); }); },\n    printLast: function () { if (lastReceipt) printReceipt(lastReceipt); },\n    voucher: function (kind, id) {\n      var e = id ? A.journal.filter(function (x) { return x.id === id; })[0] : null, x = (e && e.extra) || {}, isInc = kind === 'income';\n      var accts = A.accounts.filter(function (a) { return a.type === kind && a.code !== '4000'; });          // 4000 is invoice revenue, posted automatically\n      var def = e ? x.category : (isInc ? '4100' : (accts[0] || {}).code);\n      var opts = accts.map(function (a) { return '<option value=\"' + esc(a.code) + '\"' + (a.code === def ? ' selected' : '') + '>' + esc(a.name) + '</option>'; }).join('');\n      var curs = Object.keys(CURR).map(function (c) { return '<option' + (c === (e ? e.currency : cur) ? ' selected' : '') + '>' + c + '</option>'; }).join('');\n      modal('<h3>' + (e ? '✎ Edit ' + esc(x.voucherNo || '') : (isInc ? '＋ New Income' : '＋ New Expense')) + '</h3>' +\n        '<div class=\"grid3\"><div class=\"fld\"><label>Date</label><input id=\"vDate\" type=\"date\" value=\"' + (e ? esc(e.date) : today()) + '\"></div>' +\n        '<div class=\"fld\"><label>Amount</label><input id=\"vAmt\" type=\"number\" step=\"0.01\" min=\"0\" value=\"' + (e ? voucherAmt(e) : '') + '\"></div>' +\n        '<div class=\"fld\"><label>Currency</label><select id=\"vCur\">' + curs + '</select></div></div>' +\n        '<div class=\"grid2\" style=\"margin-top:10px;\"><div class=\"fld\"><label>' + (isInc ? 'Income category' : 'What was the expense for?') + '</label><select id=\"vCat\">' + opts + '</select></div>' +\n        '<div class=\"fld\"><label>…or a new category</label><input id=\"vNewCat\" placeholder=\"' + (isInc ? 'e.g. Commission, Rental income' : 'e.g. Fuel, Insurance, Marketing') + '\"></div></div>' +\n        '<div class=\"grid2\" style=\"margin-top:10px;\"><div class=\"fld\"><label>' + (isInc ? 'Received in' : 'Paid from') + '</label><select id=\"vMeth\"><option' + (x.method === 'Cash' ? '' : ' selected') + '>Bank</option><option' + (x.method === 'Cash' ? ' selected' : '') + '>Cash</option></select></div>' +\n        '<div class=\"fld\"><label>' + (isInc ? 'Received from' : 'Paid to') + '</label><input id=\"vParty\" value=\"' + esc(x.party || '') + '\"></div></div>' +\n        '<div class=\"grid2\" style=\"margin-top:10px;\"><div class=\"fld\"><label>Description</label><input id=\"vDesc\" value=\"' + esc(x.description || '') + '\"></div>' +\n        '<div class=\"fld\"><label>Reference / bill no</label><input id=\"vRef\" value=\"' + esc(x.ref || '') + '\"></div></div>' +\n        '<p class=\"autosave-note\">Posted automatically: ' + (isInc ? '<b>Dr</b> Cash / Bank, <b>Cr</b> the income category.' : '<b>Dr</b> the expense category, <b>Cr</b> Cash / Bank.') + '</p>' +\n        '<div class=\"m-actions\">' + CANCEL + '<button class=\"btn btn-orange\" onclick=\"ACC.saveVoucher(\\'' + kind + '\\',\\'' + (e ? e.id : '') + '\\')\">💾 Save</button></div>');\n    },\n    saveVoucher: function (kind, id) {\n      var v = { id: id || '', kind: kind, date: gv('vDate'), amount: gv('vAmt'), currency: gv('vCur'), category: gv('vCat'), newCategory: gv('vNewCat'),\n                method: gv('vMeth'), party: gv('vParty'), description: gv('vDesc'), ref: gv('vRef') };\n      call('accSaveVoucher', v, function (r) { A = r; cur = v.currency || cur; curPicked = true; tab = 'vouchers'; render(); toast('✔ ' + (kind === 'income' ? 'Income' : 'Expense') + ' saved'); });\n    },\n    newEntry: function () {\n      var opts = A.accounts.map(function (a) { return '<option value=\"' + esc(a.code) + '\">' + esc(a.code + ' · ' + a.name) + '</option>'; }).join(''), ln = '';\n      for (var i = 0; i < 4; i++) ln += '<div class=\"jrow\"><select class=\"j-acc\"><option value=\"\">— account —</option>' + opts + '</select><input class=\"j-dr\" type=\"number\" step=\"0.01\" placeholder=\"Debit\"><input class=\"j-cr\" type=\"number\" step=\"0.01\" placeholder=\"Credit\"></div>';\n      modal('<h3>New Journal Entry</h3><div class=\"grid3\"><div class=\"fld\"><label>Date</label><input id=\"jDate\" type=\"date\" value=\"' + today() + '\"></div>' +\n        '<div class=\"fld\"><label>Currency</label><select id=\"jCur\">' + Object.keys(CURR).map(function (c) { return '<option' + (c === cur ? ' selected' : '') + '>' + c + '</option>'; }).join('') + '</select></div>' +\n        '<div class=\"fld\"><label>Memo</label><input id=\"jMemo\" placeholder=\"e.g. Office rent\"></div></div><div style=\"margin-top:10px;\">' + ln + '</div>' +\n        '<p class=\"autosave-note\">Debits must equal credits. Example, rent paid by bank: <b>Dr 5200 Rent &amp; Utilities</b>, <b>Cr 1100 Bank</b>.</p>' +\n        '<div class=\"m-actions\">' + CANCEL + '<button class=\"btn btn-orange\" onclick=\"ACC.saveEntry()\">💾 Save Entry</button></div>');\n    },\n    saveEntry: function () {\n      var lines = [].map.call(root.querySelectorAll('.jrow'), function (r) {\n        return { acc: r.querySelector('.j-acc').value, dr: r.querySelector('.j-dr').value, cr: r.querySelector('.j-cr').value };\n      });\n      call('accSaveEntry', { date: gv('jDate'), currency: gv('jCur'), memo: gv('jMemo'), lines: lines },\n        function (r) { A = r; cur = gv('jCur') || cur; curPicked = true; render(); toast('✔ Journal entry saved'); });\n    },\n    del: function (id) {\n      if (!confirm('Delete this entry?')) return;\n      call('accDeleteEntry', id, function (r) { A = r; render(); toast('🗑 Entry deleted'); });\n    },\n    edit: function (ix) {\n      var a = A.accounts[ix]; if (!a) return;\n      setv('aCode', a.code); setv('aName', a.name); setv('aType', a.type);\n    },\n    saveAcc: function () {\n      call('accSaveAccount', { code: gv('aCode'), name: gv('aName'), type: gv('aType') }, function (r) { A = r; render(); toast('✔ Account saved'); });\n    },\n    csv: function () {\n      var o = [];\n      root.querySelectorAll('.rpt-sec').forEach(function (s) {\n        o.push('\"' + s.querySelector('h3').textContent + ' (' + cur + ')\"');\n        s.querySelectorAll('tr').forEach(function (r) {\n          o.push([].map.call(r.children, function (c) { return '\"' + c.textContent.replace(/,/g, '').replace(/\"/g, '\"\"') + '\"'; }).join(','));\n        });\n        o.push('');\n      });\n      var a = document.createElement('a');\n      a.href = URL.createObjectURL(new Blob([o.join('\\n')], { type: 'text/csv' }));\n      a.download = 'accounting-reports-' + cur + '.csv'; a.click();\n    }\n  };\n\n  function showJob(d) {\n    var s = window.JOBAPI ? window.JOBAPI.summary(d) : { sell: 0, cost: 0, profit: 0 };\n    modal('<h3>📄 Job ' + esc(d.jobNo) + '</h3><div class=\"rc-sum\"><div>Customer<b>' + esc(d.customer || '—') + '</b></div><div>Invoice<b>' + esc(d.invoiceNo || '—') + '</b></div>' +\n      '<div>Selling<b>' + n2(s.sell) + ' ' + esc(d.currency) + '</b></div><div>Profit<b>' + n2(s.profit) + ' ' + esc(d.currency) + '</b></div></div>' +\n      '<p class=\"autosave-note\">Press <b>Print / Save as PDF</b>, then choose <b>Save as PDF</b>. The cost sheet is marked internal because it shows agent costs.</p>' +\n      '<div class=\"m-actions\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"ACC.close()\">Close</button>' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"ACC.openJobPanel()\">Open in JOB panel</button>' +\n      '<button class=\"btn btn-orange\" onclick=\"ACC.printJobLast()\">🖨 Print / Save as PDF</button></div>');\n  }\n  function showReceipt(r, isNew) {\n    modal('<h3>' + (isNew ? '✔ Payment received — ' : '🧾 Receipt ') + esc(r.receiptNo) + '</h3><div class=\"rc-sum\">' +\n      '<div>Customer<b>' + esc(r.customer || '—') + '</b></div><div>Amount received<b>' + n2(r.amount) + ' ' + esc(r.currency) + '</b></div>' +\n      '<div>Against invoice<b>' + esc(r.invoiceNo || '—') + '</b></div><div>Balance due<b>' + n2(r.balance) + ' ' + esc(r.currency) + '</b></div></div>' +\n      '<p class=\"autosave-note\">Press <b>Print / Save as PDF</b>, then choose <b>Save as PDF</b> in the print window to get the A4 receipt and share it with the customer.</p>' +\n      '<div class=\"m-actions\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"ACC.close()\">Close</button>' +\n      '<button class=\"btn btn-orange\" onclick=\"ACC.printLast()\">🖨 Print / Save as PDF</button></div>');\n  }\n  var shellOrig = window.buildPrintShell;\n  function bankHead() { return document.querySelector('#printArea .p-bank h4'); }\n  function resetReceiptPrint() {\n    window.__rcptPrint = false; document.documentElement.removeAttribute('data-print');\n    var h = bankHead(); if (h) h.textContent = 'BANK DETAILS';\n  }\n  /* the invoice / quotation / delivery-note printers must always find the normal 'BANK DETAILS' heading */\n  window.buildPrintShell = function (o) { var h = bankHead(); if (h) h.textContent = 'BANK DETAILS'; return shellOrig(o); };\n  var origBefore = window.onbeforeprint, origAfter = window.onafterprint, origPrint = window.printCurrentDoc;\n  window.onbeforeprint = function () { if (window.__rcptPrint) return; if (origBefore) origBefore(); };\n  window.onafterprint = function () { resetReceiptPrint(); if (origAfter) origAfter(); };\n  window.printCurrentDoc = function () { resetReceiptPrint(); return origPrint(); };\n\n  /* A4 PAYMENT RECEIPT — built on the same print layout as the TAX INVOICE */\n  function printReceipt(r) {\n    var c = r.currency, co = r.company || {}, bh = r.country === 'Bahrain';\n    if (!co.name) {                                    // invoice row no longer exists: fall back to the company panel\n      co = { name: gv('coName'), address: gv('coAddress'), phone: gv('coPhone'), email: gv('coEmail'), taxNo: gv('coTaxNo') };\n      bh = !!currentBranch && currentBranch.country === 'Bahrain';\n    }\n    var rowF = function (label, v) { return '<tr><td colspan=\"2\" class=\"r\">' + label + '</td><td class=\"r\">' + fmt(v, c) + '</td></tr>'; };\n    var body = '<tr><td>1</td><td>Payment received against Tax Invoice <b>' + esc(r.invoiceNo || '') + '</b>' + (r.invoiceDate ? ' dated ' + esc(r.invoiceDate) : '') + '</td><td class=\"r\">' + fmt(r.amount, c) + '</td></tr>';\n    var foot = rowF('Invoice total', r.invoiceTotal) + rowF('Total received to date (incl. this receipt)', r.paidToDate) + rowF('Balance due', r.balance) +\n      '<tr><td colspan=\"2\" class=\"r\" style=\"font-size:14px;\">AMOUNT RECEIVED</td><td class=\"r\" style=\"color:var(--orange);font-size:14px;\">' + fmt(r.amount, c) + '</td></tr>';\n    var words = numberToWords(r.amount, c);\n    shellOrig({\n      logo: LOGO_SRC, title: 'PAYMENT RECEIPT', partyLabel: 'Received From',\n      companyName: co.name, companyAddress: co.address, companyLine2: [co.phone, co.email].filter(Boolean).join(' | '),\n      companyLine3: co.taxNo ? ((bh ? 'VAT Reg No: ' : 'GST Reg No: ') + co.taxNo) : '',\n      partyName: r.customer, partyAddress: r.customerAddress, partyExtra: r.customerTaxNo ? ((bh ? 'VAT No: ' : 'GSTIN: ') + r.customerTaxNo) : '',\n      meta: [['Receipt No:', r.receiptNo, true], ['Receipt Date:', r.date], ['Against Invoice:', r.invoiceNo], ['Invoice Date:', r.invoiceDate],\n             ['Payment Mode:', r.method], ['Reference:', r.reference]],\n      itemsHead: '<tr><th style=\"width:36px;\">#</th><th>Description</th><th style=\"width:150px;\" class=\"r\">Amount</th></tr>',\n      itemsBody: body, itemsFoot: foot, words: words ? words + ' Only' : '', terms: '', bankSource: 'branch'\n    });\n    var h = bankHead(); if (h) h.textContent = 'PAYMENT DETAILS';\n    document.getElementById('pBank').innerHTML = '<b>Payment mode:</b> ' + esc(r.method || '') + (r.reference ? '<br><b>Reference:</b> ' + esc(r.reference) : '') +\n      '<br><b>Received on:</b> ' + esc(r.date);\n    document.documentElement.setAttribute('data-print', 'receipt');\n    window.__rcptPrint = true;\n    fitPrintToOnePage(); window.print();\n  }\n\n  /* hook into the original tab switcher without altering it */\n  var orig = window.switchDoc;\n  window.switchDoc = function (t) {\n    orig(t);\n    document.documentElement.removeAttribute('data-print');\n    var on = t === 'acc';\n    root.style.display = on ? '' : 'none';\n    document.getElementById('tabAcc').classList.toggle('active', on);\n    if (on) load();\n  };\n})();\n</script>\n<script>\n/* QUOTATION → INVOICE\n   - \"Load Quotation\": pick a saved quotation (so it can be converted days later, once the customer confirms)\n   - \"Convert to Invoice\": copies customer, items, amounts and shipment details into the normal TAX INVOICE form.\n     Nothing is saved until you press Save to Cloud there; anything extra is added by hand as usual.\n   Uses only the page's existing functions (run, selectBranch, applyTaxMode, addItemRow, computeTotals ...). */\n(function () {\n  var cache = [], shown = [], pending = null, loaded = null;\n  var el = function (id) { return document.getElementById(id); };\n\n  /* ---------- buttons + picker modal (added next to the existing quotation buttons) ---------- */\n  var bar = document.querySelector('#viewQuote .btn-bar');\n  if (bar) {\n    bar.insertAdjacentHTML('beforeend',\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"QINV.openList()\">&#128194; Load Quotation</button>' +\n      '<button class=\"btn btn-orange\" onclick=\"QINV.convert()\">&#129534; Convert to Invoice</button>');\n  }\n  document.body.insertAdjacentHTML('beforeend',\n    '<div class=\"modal-back no-print\" id=\"quoteListModal\"><div class=\"modal\" style=\"width:640px;\">' +\n    '<h3>Load Quotation from Cloud</h3>' +\n    '<div class=\"fld\" style=\"margin-bottom:10px;\"><input id=\"qlSearch\" placeholder=\"🔍 Search by quotation no, customer or date…\" oninput=\"QINV.filter()\"></div>' +\n    '<div id=\"qlList\" style=\"max-height:50vh; overflow:auto;\"></div>' +\n    '<div class=\"m-actions\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"QINV.closeList()\">Cancel</button></div>' +\n    '</div></div>');\n\n  function rows(list) {\n    shown = list;\n    var c = el('qlList');\n    if (!list.length) { c.innerHTML = '<div style=\"padding:18px;text-align:center;color:var(--muted);\">No quotations found in the system.</div>'; return; }\n    c.innerHTML = list.map(function (v, i) {\n      var done = v.status === 'Converted';\n      return '<div onclick=\"QINV.load(' + i + ')\" style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;' +\n        'border:1px solid var(--line);border-radius:8px;margin-bottom:8px;cursor:pointer;background:#fff;\" ' +\n        'onmouseover=\"this.style.background=\\'#efe9fa\\'\" onmouseout=\"this.style.background=\\'#fff\\'\">' +\n        '<div><b style=\"color:var(--purple);\">' + esc(v.quotationNo) + '</b> <span style=\"color:var(--muted);font-size:12px;\">' + esc(v.quotationDate) + '</span>' +\n        (done ? ' <span class=\"st st-Paid\">✔ Invoiced ' + esc(v.invoiceNo) + '</span>' : '') +\n        '<div style=\"font-size:12px;color:var(--muted);\">' + esc(v.quoteTo || '—') + '</div></div>' +\n        '<div style=\"font-weight:700;white-space:nowrap;\">' + esc(String(v.grandTotal)) + ' ' + esc(v.currency) + '</div></div>';\n    }).join('');\n  }\n\n  /* ---------- load a saved quotation into the quotation form ---------- */\n  function fill(d, meta) {\n    setv('quotNo', d.quotationNo); setv('quotDate', d.quotationDate);\n    setv('compName', d.companyName); setv('compAddr', d.companyAddress); setv('compWeb', d.website); setv('compCR', d.crNumber);\n    setv('custName', d.quoteTo); setv('custAddr', d.customerAddress); setv('custMobile', d.customerMobile);\n    setv('blNo', d.blNo); setv('numPcs', d.numPcs); setv('shipOrigin', d.origin); setv('shipDest', d.destination);\n    setv('grossWt', d.grossWeight); setv('chargeWt', d.chargeableWeight); setv('qCommodity', d.commodity);\n    setv('qShipMode', d.shipMode); setv('qShipTerms', d.shipTerms); setv('invCurrency', d.currency); setv('vatRate', d.vatRate);\n    setv('termsConditions', d.terms);\n    lineItems = (d.items && d.items.length ? d.items : [{ desc: '', hsCode: '', qty: 1, price: 0, vat: 0 }]).map(function (it) {\n      return { desc: String(it.desc || ''), hsCode: String(it.hsCode || ''), qty: parseFloat(it.qty) || 0, price: parseFloat(it.price) || 0, vat: parseFloat(it.vat) || 0 };\n    });\n    renderQuoteItems();\n    loaded = { no: d.quotationNo, status: meta.status, invoiceNo: meta.invoiceNo };\n  }\n\n  /* ---------- convert the quotation on screen into an invoice ---------- */\n  function convert() {\n    var items = lineItems.filter(function (i) { return String(i.desc || '').trim() || i.price; });\n    if (!gv('custName')) { toast('⚠ Enter the customer name first', true); return; }\n    if (!items.length) { toast('⚠ Add at least one line item', true); return; }\n    var no = gv('quotNo'), cur = el('invCurrency').value;\n    var msg = 'Convert quotation ' + no + ' to a TAX INVOICE?\\n\\nCustomer, items, amounts and shipment details are copied into the invoice form.\\nYou can add anything extra there before saving.';\n    if (loaded && loaded.no === no && loaded.status === 'Converted') {\n      msg = 'Quotation ' + no + ' was already converted to ' + loaded.invoiceNo + '.\\n\\nCreate another invoice from it?';\n    }\n    if (!confirm(msg)) return;\n\n    /* effective tax rate keeps the invoice total identical to the quotation even if lines had different VAT % */\n    var sub = 0, vat = 0, rates = {};\n    items.forEach(function (it) { sub += it.qty * it.price; vat += it.qty * it.price * (it.vat / 100); rates[it.vat] = 1; });\n    var rate = sub ? round2(vat / sub * 100) : 0, mixed = Object.keys(rates).length > 1;\n\n    switchDoc('invoice');\n    /* India (GST) for INR quotations, otherwise the Bahrain (VAT) branch — unless the right country is already selected */\n    var target = cur === 'INR' ? 'India' : 'Bahrain';\n    if (!currentBranch || currentBranch.country !== target) {\n      var b = branches.filter(function (x) { return x.country === target; })[0];\n      if (b) selectBranch(b.name);\n    }\n    editingInvoiceNo = '';\n    ['placeSupply', 'terms', 'awbNo', 'commodity', 'grossWeight', 'volume', 'billTo', 'billToAddress', 'billToTaxNo', 'shipMode', 'shipTerms']\n      .forEach(function (id) { el(id).value = ''; });\n    el('invDate').valueAsDate = new Date();\n    setv('billTo', gv('custName')); setv('billToAddress', gv('custAddr'));\n    setv('awbNo', gv('blNo')); setv('commodity', gv('qCommodity')); setv('grossWeight', gv('grossWt'));\n    setv('shipMode', el('qShipMode').value); setv('shipTerms', el('qShipTerms').value);\n\n    var invCur = cur === 'EURO' ? 'EUR' : cur, warn = '';\n    if ([].some.call(el('currency').options, function (o) { return o.value === invCur; })) el('currency').value = invCur;\n    else warn = ' (currency ' + cur + ' is not in the invoice list — please choose it)';\n\n    el('itemsBody').innerHTML = '';\n    items.forEach(function (it) {\n      addItemRow();\n      var rs = document.querySelectorAll('#itemsBody tr'), r = rs[rs.length - 1];\n      r.querySelector('.i-desc').value = String(it.desc || '') + (String(it.hsCode || '').trim() ? ' (HS Code: ' + String(it.hsCode).trim() + ')' : '');\n      r.querySelector('.i-qty').value = it.qty;\n      r.querySelector('.i-rate').value = it.price;\n    });\n    applyTaxMode();\n    if (currentBranch && currentBranch.country === 'India') { el('taxRate1').value = rate / 2; el('taxRate2').value = rate / 2; }\n    else el('taxRate1').value = rate;\n    computeTotals();\n\n    run('getNextInvoiceNo', function (n) { el('invNo').value = n; lastAutoInvNo = n; });\n    el('syncInfo').textContent = '📋 From quotation ' + no;\n    pending = { no: no };\n    toast('🧾 Invoice prepared from ' + no + ' — add anything extra, then Save to Cloud' + (mixed ? ' (mixed VAT rates averaged)' : '') + warn);\n  }\n\n  window.QINV = {\n    openList: function () {\n      el('qlSearch').value = ''; el('quoteListModal').classList.add('open');\n      el('qlList').innerHTML = '<div style=\"padding:18px;text-align:center;color:var(--muted);\">Loading quotations from cloud…</div>';\n      run('getQuotationList', function (l) { cache = l || []; rows(cache); });\n    },\n    closeList: function () { el('quoteListModal').classList.remove('open'); },\n    filter: function () {\n      var q = el('qlSearch').value.toLowerCase();\n      rows(cache.filter(function (v) { return (v.quotationNo + ' ' + (v.quoteTo || '') + ' ' + v.quotationDate).toLowerCase().indexOf(q) !== -1; }));\n    },\n    load: function (i) {\n      var v = shown[i]; if (!v) return;\n      toast('Loading ' + v.quotationNo + '…');\n      run('getQuotation', function (d) {\n        fill(d, v); QINV.closeList();\n        toast('📂 Loaded ' + d.quotationNo + (v.status === 'Converted' ? ' (already invoiced as ' + v.invoiceNo + ')' : ' — press Convert to Invoice once the customer confirms'));\n      }, v.quotationNo);\n    },\n    convert: convert\n  };\n\n  /* ---------- after the new invoice is saved, flag the quotation as converted (the invoice save itself is untouched) ---------- */\n  var origRun = window.run;\n  window.run = function (fn, ok, arg) {\n    if (fn === 'saveInvoice' && pending && arg) {\n      var conv = pending, inner = ok;\n      ok = function (res) {\n        origRun('quoteMarkConverted', null, { quotationNo: conv.no, invoiceNo: res && res.invoiceNo });\n        pending = null;\n        if (inner) inner(res);\n      };\n    }\n    return origRun(fn, ok, arg);\n  };\n  /* starting/loading another invoice cancels the pending link, so a different invoice is never tagged by mistake */\n  ['newInvoice', 'loadInvoiceIntoPanel'].forEach(function (name) {\n    var f = window[name];\n    if (typeof f === 'function') window[name] = function () { pending = null; return f.apply(this, arguments); };\n  });\n})();\n</script>\n<script>\n/* JOB panel — a cost sheet per job / invoice.\n   Each line: description, qty, SELLING rate, QUOTED AGENT, COST  ->  profit per line and per job.\n   \"Pull from Invoice\" copies the invoice (customer, shipment details, lines at their selling rate) so nothing is typed twice;\n   the agent and cost are then added by hand. Saved jobs feed the ACCOUNTING tab (profit per job / invoice, cost posted to the books).\n   Built on the page's own helpers (run, setv, gv, esc, toast, fmt, buildPrintShell ...). */\n(function () {\n  var items = [], editing = '', branchObj = null, listCache = [], shownJobs = [], invCache = [], shownInv = [];\n  var el = function (id) { return document.getElementById(id); };\n  var n2 = function (v) { v = Math.round((v || 0) * 100) / 100; if (!v) v = 0; return v.toFixed(2); };\n  var UNITS = ['Pcs', 'Palette', 'Boxes', 'Package', 'Days', 'Services'];\n  var blank = function () { return { desc: '', qty: 1, unit: 'Pcs', rate: 0, agent: '', cost: 0 }; };\n\n  /* ---------- tab button + panel ---------- */\n  el('tabAcc').insertAdjacentHTML('beforebegin', '<button class=\"doc-tab\" id=\"tabJob\" onclick=\"switchDoc(\\'job\\')\">&#128188; JOB</button>');\n  function copyOptions(srcId, ownId, ph) {   // same choices as the invoice form (select) so both screens always agree\n    var src = el(srcId);\n    return src && src.tagName === 'SELECT' ? '<select id=\"' + ownId + '\">' + src.innerHTML + '</select>' : '<input id=\"' + ownId + '\" placeholder=\"' + ph + '\">';\n  }\n  el('printArea').insertAdjacentHTML('beforebegin',\n    '<div id=\"viewJob\" class=\"no-print\" style=\"display:none;\"><div class=\"wrap\" style=\"grid-template-columns:1fr; max-width:1100px;\">' +\n    '<div class=\"card\"><h3>Job Details</h3>' +\n    '<div class=\"grid3\">' +\n      '<div class=\"fld\"><label>Job No (auto — editable)</label><input id=\"jNo\" style=\"background:#efe9fa;font-weight:700;color:var(--purple);\"></div>' +\n      '<div class=\"fld\"><label>Job Date</label><input id=\"jDate\" type=\"date\"></div>' +\n      '<div class=\"fld\"><label>Invoice No (linked)</label><input id=\"jInvNo\" placeholder=\"e.g. WRL-INV-0001\"></div>' +\n    '</div>' +\n    '<div class=\"btn-bar\" style=\"margin:10px 0 0;\"><button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"JOB.openInvoices()\">&#128229; Pull from Invoice</button>' +\n      '<span id=\"jInfo\" style=\"align-self:center;font-size:12px;color:var(--muted);font-weight:700;\"></span></div>' +\n    '<div class=\"grid3\" style=\"margin-top:12px;\">' +\n      '<div class=\"fld\"><label>Branch / Company</label><select id=\"jBranch\" onchange=\"JOB.branchChanged()\"></select></div>' +\n      '<div class=\"fld\"><label>Currency</label><select id=\"jCurrency\" onchange=\"JOB.totals()\">' + (el('currency') ? el('currency').innerHTML : '<option>BHD</option>') + '</select></div>' +\n    '</div></div>' +\n    '<div class=\"card\"><h3>Customer &amp; Shipment</h3>' +\n    '<div class=\"grid2\"><div class=\"fld\"><label>Customer (Bill To)</label><input id=\"jBillTo\" placeholder=\"Customer name\"></div>' +\n      '<div class=\"fld\"><label>Customer Address</label><input id=\"jAddr\" placeholder=\"Address\"></div></div>' +\n    '<div class=\"grid3\" style=\"margin-top:10px;\">' +\n      '<div class=\"fld\"><label>AWB / BL No</label><input id=\"jAwb\"></div>' +\n      '<div class=\"fld\"><label>Commodity</label><input id=\"jCommodity\" placeholder=\"e.g. General Cargo\"></div>' +\n      '<div class=\"fld\"><label>Gross Weight (KG)</label><input id=\"jWeight\"></div>' +\n      '<div class=\"fld\"><label>Volume (CBM)</label><input id=\"jVolume\"></div>' +\n      '<div class=\"fld\"><label>Shipment Mode</label>' + copyOptions('shipMode', 'jMode', 'e.g. Air Freight') + '</div>' +\n      '<div class=\"fld\"><label>Shipment Terms</label>' + copyOptions('shipTerms', 'jTerms', 'e.g. CIF') + '</div>' +\n      '<div class=\"fld\"><label>Origin</label><input id=\"jOrigin\" placeholder=\"e.g. Dubai\"></div>' +\n      '<div class=\"fld\"><label>Destination</label><input id=\"jDest\" placeholder=\"e.g. Manama\"></div>' +\n    '</div></div>' +\n    '<div class=\"card\"><h3>Job Cost Sheet — selling, quoted agent, cost</h3>' +\n    '<div class=\"acc-scroll\"><table class=\"items\" id=\"jTable\"><thead><tr><th style=\"width:34px;\">#</th><th>Description</th><th style=\"width:72px;\">Qty</th><th style=\"width:104px;\">Unit</th>' +\n      '<th style=\"width:110px;\">Selling Rate</th><th style=\"width:104px;\" class=\"num\">Selling Amt</th><th style=\"width:170px;\">Quoted Agent</th>' +\n      '<th style=\"width:110px;\">Cost</th><th style=\"width:100px;\" class=\"num\">Profit</th><th style=\"width:34px;\"></th></tr></thead><tbody id=\"jItems\"></tbody></table></div>' +\n    '<datalist id=\"jAgents\"></datalist>' +\n    '<button class=\"add-row-btn\" onclick=\"JOB.add()\">＋ Add Line</button>' +\n    '<div class=\"totals\">' +\n      '<div class=\"trow\"><span>Total Selling</span><b id=\"jSell\">0.00</b></div>' +\n      '<div class=\"trow\"><span>Total Cost (agents)</span><b id=\"jCost\">0.00</b></div>' +\n      '<div class=\"trow grand\"><span>PROFIT</span><b id=\"jProfit\" style=\"color:var(--orange);\">0.00</b></div>' +\n      '<div class=\"trow\"><span>Margin</span><b id=\"jMargin\">0.0 %</b></div>' +\n    '</div>' +\n    '<div class=\"fld\" style=\"margin-top:14px;\"><label>Remarks (internal)</label><textarea id=\"jRemarks\" placeholder=\"Notes for this job\"></textarea></div>' +\n    '<div class=\"btn-bar\">' +\n      '<button class=\"btn btn-orange\" onclick=\"JOB.save()\">&#128190; Save Job</button>' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"JOB.print()\">&#128424; Print / Save as PDF</button>' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--purple);\" onclick=\"JOB.openList()\">&#128194; Load Job</button>' +\n      '<button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"JOB.reset(true)\">&#128260; New Job</button>' +\n      '<button class=\"btn btn-white\" id=\"jDelete\" style=\"border:1px solid #c0392b;color:#c0392b;display:none;\" onclick=\"JOB.remove()\">&#128465; Delete Job</button>' +\n    '</div></div>' +\n    '</div></div>');\n  document.body.insertAdjacentHTML('beforeend',\n    '<div class=\"modal-back no-print\" id=\"jobListModal\"><div class=\"modal\" style=\"width:680px;\"><h3>Load Job from Cloud</h3>' +\n    '<div class=\"fld\" style=\"margin-bottom:10px;\"><input id=\"jlSearch\" placeholder=\"🔍 Search by job no, customer, invoice or agent…\" oninput=\"JOB.filterJobs()\"></div>' +\n    '<div id=\"jlList\" style=\"max-height:50vh;overflow:auto;\"></div>' +\n    '<div class=\"m-actions\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"JOB.closeModals()\">Cancel</button></div></div></div>' +\n    '<div class=\"modal-back no-print\" id=\"jobInvModal\"><div class=\"modal\" style=\"width:680px;\"><h3>Pull details from an Invoice</h3>' +\n    '<div class=\"fld\" style=\"margin-bottom:10px;\"><input id=\"jiSearch\" placeholder=\"🔍 Search by invoice no, customer or date…\" oninput=\"JOB.filterInv()\"></div>' +\n    '<div id=\"jiList\" style=\"max-height:50vh;overflow:auto;\"></div>' +\n    '<div class=\"m-actions\"><button class=\"btn btn-white\" style=\"border:1px solid var(--line);\" onclick=\"JOB.closeModals()\">Cancel</button></div></div></div>');\n\n  /* ---------- model ---------- */\n  function lineSell(it) { return round2((it.qty || 0) * (it.rate || 0)); }\n  function calc() {\n    var s = 0, c = 0;\n    items.forEach(function (it) { s += lineSell(it); c += it.cost || 0; });\n    s = round2(s); c = round2(c);\n    return { sell: s, cost: c, profit: round2(s - c), margin: s ? round2((s - c) / s * 100) : 0 };\n  }\n  function totals() {\n    var t = calc(), cur = gv('jCurrency');\n    el('jSell').textContent = n2(t.sell) + ' ' + cur; el('jCost').textContent = n2(t.cost) + ' ' + cur;\n    el('jProfit').textContent = n2(t.profit) + ' ' + cur; el('jProfit').style.color = t.profit < 0 ? '#c0392b' : 'var(--orange)';\n    el('jMargin').textContent = t.margin.toFixed(1) + ' %';\n    items.forEach(function (it, i) {\n      var a = el('jAmt' + i), p = el('jPft' + i), pr = round2(lineSell(it) - (it.cost || 0));\n      if (a) a.textContent = n2(lineSell(it));\n      if (p) { p.textContent = n2(pr); p.style.color = pr < 0 ? '#c0392b' : '#1e7a3c'; }\n    });\n  }\n  function agentList() {\n    var seen = {}, out = [];\n    listCache.forEach(function (j) { String(j.agents || '').split(',').forEach(function (a) { a = a.trim(); if (a && !seen[a.toLowerCase()]) { seen[a.toLowerCase()] = 1; out.push(a); } }); });\n    items.forEach(function (it) { var a = (it.agent || '').trim(); if (a && !seen[a.toLowerCase()]) { seen[a.toLowerCase()] = 1; out.push(a); } });\n    el('jAgents').innerHTML = out.map(function (a) { return '<option value=\"' + esc(a) + '\">'; }).join('');\n  }\n  function renderItems() {\n    if (!items.length) items = [blank()];\n    el('jItems').innerHTML = items.map(function (it, i) {\n      return '<tr><td>' + (i + 1) + '</td>' +\n        '<td><input value=\"' + esc(it.desc) + '\" placeholder=\"e.g. Air freight DXB - BAH\" oninput=\"JOB.set(' + i + ',\\'desc\\',this.value)\"></td>' +\n        '<td><input type=\"number\" step=\"any\" min=\"0\" class=\"num\" value=\"' + it.qty + '\" oninput=\"JOB.set(' + i + ',\\'qty\\',this.value)\"></td>' +\n        '<td><select onchange=\"JOB.set(' + i + ',\\'unit\\',this.value)\">' + UNITS.map(function (u) { return '<option' + (u === it.unit ? ' selected' : '') + '>' + u + '</option>'; }).join('') + '</select></td>' +\n        '<td><input type=\"number\" step=\"any\" min=\"0\" class=\"num\" value=\"' + it.rate + '\" oninput=\"JOB.set(' + i + ',\\'rate\\',this.value)\"></td>' +\n        '<td class=\"num\" id=\"jAmt' + i + '\"></td>' +\n        '<td><input list=\"jAgents\" value=\"' + esc(it.agent) + '\" placeholder=\"Agent / vendor\" oninput=\"JOB.set(' + i + ',\\'agent\\',this.value)\"></td>' +\n        '<td><input type=\"number\" step=\"any\" min=\"0\" class=\"num\" value=\"' + it.cost + '\" oninput=\"JOB.set(' + i + ',\\'cost\\',this.value)\"></td>' +\n        '<td class=\"num\" id=\"jPft' + i + '\"></td>' +\n        '<td><button class=\"row-del\" title=\"Remove line\" onclick=\"JOB.del(' + i + ')\">✕</button></td></tr>';\n    }).join('');\n    agentList(); totals();\n  }\n\n  /* ---------- form <-> data ---------- */\n  function fillBranches(keep) {\n    var cur = keep || gv('jBranch') || (currentBranch && currentBranch.name) || '';\n    el('jBranch').innerHTML = (branches || []).map(function (b) { return '<option' + (b.name === cur ? ' selected' : '') + '>' + esc(b.name) + '</option>'; }).join('');\n    branchObj = (branches || []).filter(function (b) { return b.name === gv('jBranch'); })[0] || null;\n  }\n  function collect() {\n    var b = (branches || []).filter(function (x) { return x.name === gv('jBranch'); })[0] || {};\n    return { jobNo: gv('jNo'), originalJobNo: editing, jobDate: gv('jDate'), invoiceNo: gv('jInvNo'), branchName: gv('jBranch'), branchCountry: b.country || '',\n      customer: gv('jBillTo'), customerAddress: gv('jAddr'), currency: gv('jCurrency'), awbNo: gv('jAwb'), commodity: gv('jCommodity'),\n      grossWeight: gv('jWeight'), volume: gv('jVolume'), shipMode: gv('jMode'), shipTerms: gv('jTerms'), origin: gv('jOrigin'), destination: gv('jDest'),\n      remarks: gv('jRemarks'), items: items.map(function (it) { return { desc: it.desc, qty: it.qty, unit: it.unit, rate: it.rate, agent: it.agent, cost: it.cost }; }) };\n  }\n  function fill(d) {\n    editing = d.jobNo || '';\n    setv('jNo', d.jobNo); setv('jDate', d.jobDate); setv('jInvNo', d.invoiceNo); fillBranches(d.branchName);\n    setv('jCurrency', d.currency); setv('jBillTo', d.customer); setv('jAddr', d.customerAddress); setv('jAwb', d.awbNo); setv('jCommodity', d.commodity);\n    setv('jWeight', d.grossWeight); setv('jVolume', d.volume); setv('jMode', d.shipMode); setv('jTerms', d.shipTerms); setv('jOrigin', d.origin); setv('jDest', d.destination);\n    setv('jRemarks', d.remarks);\n    items = (d.items || []).map(function (it) {\n      return { desc: String(it.desc || ''), qty: parseFloat(it.qty) || 0, unit: it.unit || 'Pcs', rate: parseFloat(it.rate) || 0, agent: String(it.agent || ''), cost: parseFloat(it.cost) || 0 };\n    });\n    renderItems(); mode();\n  }\n  function mode() {\n    el('jInfo').textContent = editing ? '✏ Editing ' + editing + ' — Save updates this job' : 'New job';\n    el('jDelete').style.display = editing ? '' : 'none';\n  }\n  function dirty() {\n    return editing || gv('jBillTo') || items.some(function (it) { return it.agent || it.cost || it.desc; });\n  }\n  function reset(ask) {\n    if (ask && dirty() && !confirm('Start a new job?\\nUnsaved details on this screen will be cleared.')) return;\n    editing = '';\n    ['jInvNo', 'jBillTo', 'jAddr', 'jAwb', 'jCommodity', 'jWeight', 'jVolume', 'jMode', 'jTerms', 'jOrigin', 'jDest', 'jRemarks'].forEach(function (id) { el(id).value = ''; });\n    el('jDate').valueAsDate = new Date();\n    fillBranches(); setv('jCurrency', branchObj && branchObj.country === 'India' ? 'INR' : 'BHD');\n    items = [blank()]; renderItems(); mode();\n    run('getNextJobNo', function (n) { if (!editing) el('jNo').value = n; });\n  }\n\n  /* ---------- pickers ---------- */\n  function listRows(box, list, build) {\n    var c = el(box);\n    c.innerHTML = list.length ? list.map(build).join('') : '<div style=\"padding:18px;text-align:center;color:var(--muted);\">Nothing found in the system.</div>';\n  }\n  var rowStyle = 'display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;margin-bottom:8px;cursor:pointer;background:#fff;';\n  var hover = ' onmouseover=\"this.style.background=\\'#efe9fa\\'\" onmouseout=\"this.style.background=\\'#fff\\'\"';\n  function showJobs(list) {\n    shownJobs = list;\n    listRows('jlList', list, function (v, i) {\n      return '<div onclick=\"JOB.load(' + i + ')\" style=\"' + rowStyle + '\"' + hover + '><div><b style=\"color:var(--purple);\">' + esc(v.jobNo) + '</b> <span style=\"color:var(--muted);font-size:12px;\">' + esc(v.jobDate) + '</span>' +\n        (v.invoiceNo ? ' <span class=\"st\">' + esc(v.invoiceNo) + '</span>' : '') +\n        '<div style=\"font-size:12px;color:var(--muted);\">' + esc(v.customer || '—') + (v.agents ? ' · ' + esc(v.agents) : '') + '</div></div>' +\n        '<div style=\"text-align:right;white-space:nowrap;\"><div style=\"font-weight:700;\">' + n2(v.totalSelling) + ' ' + esc(v.currency) + '</div>' +\n        '<div style=\"font-size:12px;font-weight:700;color:' + (v.profit < 0 ? '#c0392b' : '#1e7a3c') + ';\">profit ' + n2(v.profit) + '</div></div></div>';\n    });\n  }\n  function showInv(list) {\n    shownInv = list;\n    listRows('jiList', list, function (v, i) {\n      return '<div onclick=\"JOB.pick(' + i + ')\" style=\"' + rowStyle + '\"' + hover + '><div><b style=\"color:var(--purple);\">' + esc(v.invoiceNo) + '</b> <span style=\"color:var(--muted);font-size:12px;\">' + esc(v.invoiceDate) + '</span>' +\n        '<div style=\"font-size:12px;color:var(--muted);\">' + esc(v.billTo || '—') + '</div></div>' +\n        '<div style=\"font-weight:700;white-space:nowrap;\">' + esc(String(v.grandTotal)) + ' ' + esc(v.currency) + '</div></div>';\n    });\n  }\n  function jobSummary(d) {\n    var t = 0, c = 0; (d.items || []).forEach(function (it) { t += round2((parseFloat(it.qty) || 0) * (parseFloat(it.rate) || 0)); c += parseFloat(it.cost) || 0; });\n    return { sell: round2(t), cost: round2(c), profit: round2(t - c) };\n  }\n\n  /* ---------- A4 PDF: JOB COST SHEET (same print layout as the invoice) ---------- */\n  function bankHead() { return document.querySelector('#printArea .p-bank h4'); }\n  function buildJobPrint(d) {\n    d = d || collect();\n    var cur = d.currency, b = (branches || []).filter(function (x) { return x.name === d.branchName; })[0] || branchObj || currentBranch || {};\n    var bh = (b.country || d.branchCountry) === 'Bahrain', its = d.items.filter(function (it) { return it.desc || it.qty || it.rate || it.cost || it.agent; });\n    var tS = 0, tC = 0;\n    var body = its.map(function (it, i) {\n      var s = round2((it.qty || 0) * (it.rate || 0)), c = round2(it.cost || 0); tS += s; tC += c;\n      var p = round2(s - c);\n      return '<tr><td>' + (i + 1) + '</td><td>' + esc(it.desc) + '</td><td class=\"r\">' + esc(String(it.qty)) + (it.unit ? ' ' + esc(it.unit) : '') + '</td><td class=\"r\">' + n2(it.rate) + '</td>' +\n        '<td class=\"r\">' + n2(s) + '</td><td>' + esc(it.agent) + '</td><td class=\"r\">' + n2(c) + '</td><td class=\"r\" style=\"' + (p < 0 ? 'color:#c0392b;' : '') + '\">' + n2(p) + '</td></tr>';\n    }).join('');\n    tS = round2(tS); tC = round2(tC);\n    var profit = round2(tS - tC), margin = tS ? round2(profit / tS * 100) : 0;\n    var foot = '<tr><td colspan=\"4\" class=\"r\">TOTAL (' + esc(cur) + ')</td><td class=\"r\">' + n2(tS) + '</td><td></td><td class=\"r\">' + n2(tC) + '</td><td class=\"r\">' + n2(profit) + '</td></tr>' +\n      '<tr><td colspan=\"7\" class=\"r\" style=\"font-size:14px;\">NET PROFIT</td><td class=\"r\" style=\"color:' + (profit < 0 ? '#c0392b' : 'var(--orange)') + ';font-size:14px;\">' + fmt(profit, cur) + '</td></tr>' +\n      '<tr><td colspan=\"7\" class=\"r\">Profit margin</td><td class=\"r\">' + margin.toFixed(1) + ' %</td></tr>';\n    window.buildPrintShell({\n      logo: LOGO_SRC, title: 'JOB COST SHEET', partyLabel: 'Customer',\n      companyName: b.companyName || gv('coName'), companyAddress: b.address || gv('coAddress'),\n      companyLine2: [b.phone || gv('coPhone'), b.email || gv('coEmail')].filter(Boolean).join(' | '),\n      companyLine3: (b.taxNo || gv('coTaxNo')) ? ((bh ? 'VAT Reg No: ' : 'GST Reg No: ') + (b.taxNo || gv('coTaxNo'))) : '',\n      partyName: d.customer, partyAddress: d.customerAddress, partyExtra: '',\n      meta: [['Job No:', d.jobNo, true], ['Job Date:', d.jobDate], ['Invoice No:', d.invoiceNo], ['AWB / BL No:', d.awbNo], ['Commodity:', d.commodity],\n             ['Gross Weight:', d.grossWeight ? d.grossWeight + ' KG' : ''], ['Volume:', d.volume ? d.volume + ' CBM' : ''], ['Shipment Mode:', d.shipMode],\n             ['Shipment Terms:', d.shipTerms], ['Route:', [d.origin, d.destination].filter(Boolean).join(' → ')]],\n      itemsHead: '<tr><th style=\"width:28px;\">#</th><th>Description</th><th class=\"r\" style=\"width:64px;\">Qty</th><th class=\"r\" style=\"width:80px;\">Selling Rate</th>' +\n        '<th class=\"r\" style=\"width:92px;\">Selling Amt</th><th style=\"width:118px;\">Quoted Agent</th><th class=\"r\" style=\"width:80px;\">Cost</th><th class=\"r\" style=\"width:84px;\">Profit</th></tr>',\n      itemsBody: body, itemsFoot: foot, words: '', terms: '', bankSource: 'branch'\n    });\n    var h = bankHead(); if (h) h.textContent = 'REMARKS';\n    el('pBank').innerHTML = '<b>INTERNAL DOCUMENT — not for the customer.</b>' + (d.remarks ? '<br>' + esc(d.remarks).replace(/\\n/g, '<br>') : '');\n  }\n  function printJob(d) {\n    buildJobPrint(d);\n    window.__rcptPrint = true;          // stops the page's own before-print hook from replacing this sheet with an invoice\n    fitPrintToOnePage(); window.print();\n  }\n\n  /* ---------- actions ---------- */\n  function onShow() {\n    if (!(branches || []).length) { run('getInitialData', function (r) { branches = r.branches; fillBranches(); }); }\n    else if (!el('jBranch').options.length) fillBranches();\n    if (!el('jNo').value && !editing) reset(false);\n    run('getJobList', function (l) { listCache = l || []; agentList(); });\n  }\n  window.JOB = {\n    totals: totals,\n    set: function (i, k, v) {\n      var it = items[i]; if (!it) return;\n      it[k] = (k === 'qty' || k === 'rate' || k === 'cost') ? (parseFloat(v) || 0) : v;\n      totals(); if (k === 'agent') agentList();\n    },\n    add: function () { items.push(blank()); renderItems(); },\n    del: function (i) { items.splice(i, 1); renderItems(); },\n    branchChanged: function () {\n      branchObj = (branches || []).filter(function (b) { return b.name === gv('jBranch'); })[0] || null;\n      if (branchObj) setv('jCurrency', branchObj.country === 'India' ? 'INR' : 'BHD');\n      totals();\n    },\n    reset: reset,\n    fillData: fill,\n    print: function () { printJob(); },\n    printData: function (d) { printJob(d); },\n    closeModals: function () { el('jobListModal').classList.remove('open'); el('jobInvModal').classList.remove('open'); },\n\n    openList: function () {\n      el('jlSearch').value = ''; el('jobListModal').classList.add('open');\n      el('jlList').innerHTML = '<div style=\"padding:18px;text-align:center;color:var(--muted);\">Loading jobs from cloud…</div>';\n      run('getJobList', function (l) { listCache = l || []; agentList(); showJobs(listCache); });\n    },\n    filterJobs: function () {\n      var q = el('jlSearch').value.toLowerCase();\n      showJobs(listCache.filter(function (v) { return (v.jobNo + ' ' + v.customer + ' ' + v.invoiceNo + ' ' + v.agents + ' ' + v.jobDate).toLowerCase().indexOf(q) !== -1; }));\n    },\n    load: function (i) {\n      var v = shownJobs[i]; if (!v) return;\n      run('getJob', function (d) { fill(d); JOB.closeModals(); toast('📂 Loaded ' + d.jobNo); }, v.jobNo);\n    },\n\n    openInvoices: function () {\n      el('jiSearch').value = ''; el('jobInvModal').classList.add('open');\n      el('jiList').innerHTML = '<div style=\"padding:18px;text-align:center;color:var(--muted);\">Loading invoices from cloud…</div>';\n      run('getInvoiceList', function (l) { invCache = l || []; showInv(invCache); });\n    },\n    filterInv: function () {\n      var q = el('jiSearch').value.toLowerCase();\n      showInv(invCache.filter(function (v) { return (v.invoiceNo + ' ' + (v.billTo || '') + ' ' + v.invoiceDate).toLowerCase().indexOf(q) !== -1; }));\n    },\n    pick: function (i) {\n      var v = shownInv[i]; if (!v) return;\n      if (dirty() && !confirm('Replace the job on screen with details from invoice ' + v.invoiceNo + '?')) return;\n      run('getJobList', function (jobs) {\n        listCache = jobs || [];\n        var have = listCache.filter(function (j) { return j.invoiceNo === v.invoiceNo; })[0];\n        if (have && confirm('A job (' + have.jobNo + ') already exists for invoice ' + v.invoiceNo + '.\\n\\nOK = open that job\\nCancel = create another job from the invoice')) {\n          run('getJob', function (d) { fill(d); JOB.closeModals(); toast('📂 Loaded ' + d.jobNo); }, have.jobNo); return;\n        }\n        run('getInvoice', function (d) {\n          reset(false); JOB.closeModals();\n          setv('jInvNo', d.invoiceNo); setv('jBillTo', d.billTo); setv('jAddr', d.billToAddress); setv('jAwb', d.awbNo); setv('jCommodity', d.commodity);\n          setv('jWeight', d.grossWeight); setv('jVolume', d.volume); setv('jMode', d.shipMode); setv('jTerms', d.shipTerms);\n          if (d.branch) { fillBranches(d.branch); }\n          setv('jCurrency', d.currency);\n          items = (d.items || []).map(function (it) { return { desc: String(it.desc || ''), qty: parseFloat(it.qty) || 0, unit: it.unit || 'Pcs', rate: parseFloat(it.rate) || 0, agent: '', cost: 0 }; });\n          renderItems();\n          toast('📥 Invoice ' + d.invoiceNo + ' pulled in — now add the quoted agent and cost on each line');\n        }, v.invoiceNo);\n      });\n    },\n\n    save: function () {\n      var d = collect(), t = calc();\n      if (!d.customer) { toast('⚠ Enter the customer name', true); return; }\n      if (!d.items.some(function (it) { return it.desc || it.rate || it.cost; })) { toast('⚠ Add at least one line', true); return; }\n      var upd = !!editing;\n      run(upd ? 'updateJob' : 'saveJob', function (res) {\n        editing = res.jobNo; el('jNo').value = res.jobNo; mode();\n        run('getJobList', function (l) { listCache = l || []; agentList(); });\n        toast('✔ ' + (upd ? 'Updated' : 'Saved') + ' — ' + res.jobNo + ' → Cloud · profit ' + n2(t.profit) + ' ' + d.currency);\n      }, d);\n    },\n    remove: function () {\n      if (!editing || !confirm('Delete job ' + editing + '?\\nIts cost is removed from the accounts.')) return;\n      run('deleteJob', function () { toast('🗑 Job deleted'); reset(false); }, editing);\n    }\n  };\n\n  /* ---------- hook into the page: tab switching and Ctrl+P ---------- */\n  var prevSwitch = window.switchDoc;\n  window.switchDoc = function (t) {\n    prevSwitch(t);\n    var on = t === 'job';\n    el('viewJob').style.display = on ? '' : 'none';\n    el('tabJob').classList.toggle('active', on);\n    if (on) onShow();\n  };\n  var prevBefore = window.onbeforeprint;\n  window.onbeforeprint = function () {\n    if (currentDoc === 'job' && !window.__rcptPrint) { buildJobPrint(); window.__rcptPrint = true; return; }\n    if (prevBefore) prevBefore();\n  };\n  /* used by the ACCOUNTING tab's job list */\n  window.JOBAPI = { print: printJob, summary: jobSummary };\n})();\n</script>\n<script>\nwindow.showUser=function(){fetch('auth/me').then(function(r){return r.ok?r.json():null}).then(function(j){var b=document.getElementById('signOutBtn');if(j&&j.user&&b){b.textContent='\\u23FB Sign out ('+j.user+')';b.style.display=''}}).catch(function(){})};\nfunction signOut(){fetch('auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).catch(function(){}).then(function(){location.reload()})}\nshowUser();\n</script>\n</body>\n</html>\n";
export const LOGIN_HTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Well Reach Logistics — Sign in</title>\n<style>\nbody{margin:0}\n.wg{position:fixed;inset:0;z-index:99999;display:grid;place-items:center;overflow:auto;background:linear-gradient(135deg,#4b2683,#2a1450);font:15px system-ui,\"Segoe UI\",Arial,sans-serif;color:#222}\n.wg *{box-sizing:border-box}\n.wg .card{background:#fff;width:min(410px,92vw);padding:30px;border-radius:14px;box-shadow:0 20px 50px rgba(0,0,0,.4)}\n.wg h1{margin:0 0 4px;font-size:20px;letter-spacing:1px;color:#4b2683}\n.wg .sub{margin:0 0 14px;color:#666;font-size:13px}\n.wg label{display:block;margin:12px 0 4px;font-size:12px;font-weight:700;color:#444}\n.wg input{width:100%;padding:11px;border:1px solid #ccc;border-radius:8px;font:inherit}\n.wg input:read-only{background:#f1eef7}\n.wg button{width:100%;margin-top:18px;padding:12px;border:0;border-radius:8px;background:#4b2683;color:#fff;font:inherit;font-weight:700;cursor:pointer}\n.wg button:disabled{opacity:.6}\n.wg .err{color:#b00020;font-size:13px;min-height:18px;margin-top:10px}\n.wg .note{background:#fff7e0;border:1px solid #f0d58a;border-radius:8px;padding:8px 10px;font-size:12px;color:#6b5200;margin-bottom:6px}\n</style></head><body>\n<main class=\"wg\" id=\"wrlGate\"><form class=\"card\" id=\"wgF\" autocomplete=\"on\">\n  <h1>WELL REACH LOGISTICS</h1><div class=\"sub\" id=\"wgSub\">Loading…</div>\n  <label>Username</label><input id=\"wgU\" name=\"username\" autocomplete=\"username\">\n  <div id=\"wgCodeBox\" hidden><label>Setup code <span style=\"font-weight:400\">(shown once in the server log / data/SETUP_CODE.txt)</span></label><input id=\"wgC\" autocomplete=\"off\"></div>\n  <label>Password</label><input id=\"wgP\" type=\"password\" autocomplete=\"current-password\">\n  <div id=\"wgConfBox\" hidden><label>Confirm password</label><input id=\"wgP2\" type=\"password\" autocomplete=\"new-password\"></div>\n  <button id=\"wgB\" type=\"submit\">Sign in</button><div class=\"err\" id=\"wgErr\"></div>\n</form></main>\n<script>\n(function(){\nvar $=function(i){return document.getElementById(i)},setup=false;\nfetch('auth/status').then(function(r){return r.json()}).then(function(s){\n  if(s.error){$('wgSub').textContent=s.error;return}\n  setup=!!s.setup;$('wgU').value=s.user;\n  $('wgSub').textContent=setup?'First logon — create your password (minimum 8 characters).':'Sign in to continue.';\n  if(setup){$('wgU').readOnly=true;$('wgCodeBox').hidden=false;$('wgConfBox').hidden=false;$('wgP').autocomplete='new-password';$('wgB').textContent='Create password & sign in';(($('wgC').value)?$('wgP'):$('wgC')).focus()}\n  else $('wgP').focus();\n}).catch(function(){$('wgSub').textContent='Cannot reach the server.'});\n$('wgF').onsubmit=function(e){\n  e.preventDefault();$('wgErr').textContent='';var pw=$('wgP').value;\n  if(setup&&pw!==$('wgP2').value){$('wgErr').textContent='Passwords do not match.';return}\n  $('wgB').disabled=true;\n  fetch(setup?'auth/setup':'auth/login',{method:'POST',headers:{'Content-Type':'application/json'},\n    body:JSON.stringify(setup?{code:$('wgC').value,password:pw}:{username:$('wgU').value,password:pw})})\n  .then(function(r){return r.json().then(function(j){return{ok:r.ok,j:j}})})\n  .then(function(x){if(x.ok){if(window.onWrlSignedIn)window.onWrlSignedIn();else location.reload()}\n    else{$('wgErr').textContent=x.j.error||'Failed.';$('wgB').disabled=false}})\n  .catch(function(){$('wgErr').textContent='Cannot reach the server.';$('wgB').disabled=false});\n};\n})();\n</script></body></html>\n";
